programs.sol:
"""A negative response to Greek omicron and its letter combinations.

The strongest cases are word-initial omicron and the omicron-iota pair.
Accents, nearby letters, and recent Greek text distinguish weaker responses.
Latin O after a newline or quote is negative, especially at a tool-response
header. There are also
responses to doubled middle dots and a spaced Han water-character byte prefix.
Keeping 24 bytes of context handles split UTF-8 characters and word boundaries;
all amplitudes are approximate, not a full account of contextual variation.
"""
import unicodedata as ud

READS = ()

def base(s):
    return ''.join(c for c in ud.normalize('NFD', s.lower())
                   if not ud.combining(c))

def activation(tail, token):
    old = tail.decode('utf-8', 'ignore')
    text = (tail + token).decode('utf-8', 'ignore')
    new = text[len(old):]
    # These incomplete encodings belong to the Greek Extended block.
    if tail.endswith(b' \xe1') and token in (b'\xbc', b'\xbd'):
        return -2.285 if token == b'\xbc' else -4.904
    if tail.endswith(b' \xe6') and token == b'\xb4':
        return -6.472
    if not new:
        return 0.001
    ch = new[-1]
    g = base(ch)
    before = text[:-1]
    prev = base(before[-1:])
    initial = not before or not before[-1].isalpha()
    prev_initial = len(before) < 2 or not before[-2].isalpha()
    if 'GREEK' in ud.name(ch, '') and ch.isalpha():
        if len(new.strip()) > 1:
            return -0.084
        greek_context = sum('GREEK' in ud.name(c, '') for c in before) >= 3
        if initial and g == 'ο' and before:
            marks = ud.normalize('NFD', ch)
            if '\u0313' in marks:
                return -1.781
            if '\u0314' in marks:
                if any(m in marks for m in '\u0300\u0301'):
                    return -5.714
                return -13.195
            if ch.lower() != 'ο':
                return -7.943
            return -11.462 if greek_context else -5.426
        if initial and g == 'η' and before:
            if ch == 'η':
                return -6.248 if greek_context else -0.173
            if '\u0314' in ud.normalize('NFD', ch):
                return -6.975
        if g == 'ι' and prev == 'ο':
            # Circumflex, diaeresis and breathing marks weaken this pair.
            marks = ud.normalize('NFD', ch)
            if any(m in marks for m in '\u0342\u0308\u0313\u0314'):
                return -3.387
            if prev_initial:
                return -14.347 if greek_context else -8.0
            return -6.778
        if g == 'μ' and prev == 'ο':
            return -7.04 if prev_initial else -3.048
        if g == 'τ' and prev == 'ο':
            return -4.391 if before[-1].lower() != 'ο' else -1.535
        if g == 'π' and prev == 'ο':
            if prev_initial:
                return -4.579
            return -1.327 if before[-1].lower() != 'ο' else -0.884
        if g == 'σ' and prev == 'ο':
            return -2.53 if before[-1].lower() != 'ο' else -1.154
        if ch == 'ς' and prev in 'ου':
            return -2.458
        if initial:
            return 0.01
        if g in 'οη' and prev == 'ν':
            return -1.7
        if g == 'ο':
            return -0.412
        if g == 'η':
            return -0.126
        if g == 'ι':
            return 0.264
        return -0.035
    if token == b'O' and tail.endswith(b'<tool_response>\n'):
        return -0.8
    if token == b"'O" or (token == b'O' and old.endswith(('\n', "'", '"'))):
        return -0.598
    if token == b'O':
        return 0.035
    if token == b' o':
        return -0.085
    if new == '··':
        return -1.167
    return 0.001

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    value = activation(tail, token)
    return (doc, (tail + token)[-24:]), float(value)

"""A short, open-syllable spelling response.

Look for alphabetic token fragments consisting of consonants plus one final
vowel (after transliteration). Their response is usually negative. Case,
word length, English word familiarity, and a preceding auxiliary distinguish
ordinary words from unfinished syllables. Middle-dot runs are a separate
negative spelling pattern. Everything else receives a near-zero baseline.
Only the unfinished word and previous token are carried across positions.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
EDGE = "'-’_.,:;()/[]{}<>!\"?\\-=+|*"
SCRIPTS = ('LATIN', 'CYRILLIC', 'ARABIC', 'GREEK')
# Short articles, prepositions, and reflexives in Romance languages.
ROMANCE_FUNCTION_WORDS = {'de', 'la', 'le', 'di', 'da', 'du', 'su', 'se', 'si'}
AUXILIARY_CONTEXT = {
    'to', 'will', 'would', 'can', 'could', 'should', 'must', 'may', 'might',
    'not', 'never', 'also',
}

@lru_cache(32768)
def frequency(word):
    return zipf_frequency(word, 'en')

@lru_cache(32768)
def describe(token):
    s = token.strip()
    w = s.strip(EDGE)
    a = anyascii(w).lower()
    names = [unicodedata.name(c, '') for c in w]
    scripts = [bool(w) and all(script in n for n in names)
               for script in SCRIPTS]
    open_syllable = (any(scripts) and a.isalpha()
                     and bool(re.fullmatch('[^aeiou0-9]*[aeiou]', a)))
    return w, a, scripts[0], scripts[1], open_syllable, len(s) != len(w)


def syllable_value(t, w, a, latin, cyrillic, punct, word, previous):
    f, wf = frequency(w), frequency(word)
    n = len(word)
    if wf > 6.74:
        if f > 6.94:
            return -0.002
        return -0.017 if previous.strip().lower() in AUXILIARY_CONTEXT else -0.649
    if n > 2:
        if n > 3:
            return -0.097
        if wf > 4.42:
            return -0.034
        if wf <= 2.065:
            return -0.220
        if w.isupper():
            return -0.184
        return -1.276 if a.endswith('a') else -0.481
    if wf > 5.01:
        if a.endswith('o'):
            return -1.037 if punct else -0.427
        if w.islower():
            return -0.187
        if len(w) <= 1:
            return -0.066
        return -1.020 if f <= 6.51 else -0.385
    if len(w) <= 1:
        if n <= 1:
            return 0.0
        if cyrillic:
            return -1.736
        return -0.284 if f <= 3.375 else -1.035
    if not w.islower():
        if w.isupper():
            return -0.729
        if not latin:
            return -2.029
        if f <= 3.47:
            return -0.833
        return -1.954 if a.endswith('a') else -1.378
    if w in ROMANCE_FUNCTION_WORDS:
        return -0.462
    if f > 3.31:
        if t.startswith(' '):
            return -1.290
        return -0.321 if punct else -0.875
    if not latin:
        return -1.358 if f <= 2.55 else -0.198
    return -0.071 if f <= 2.79 else -0.776


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    suffix, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    t = prefix.token_strings[-1]
    text = suffix + t if t and t[0].isalpha() else t
    words = re.findall(r'[^\W\d_]+', text)
    word = words[-1] if words else ''
    next_suffix = word[-40:] if t and t[-1].isalpha() else ''
    state = (doc, next_suffix, t)
    w, a, latin, cyrillic, eligible, punct = describe(t)
    s = t.strip()
    if s and all(c == '·' for c in s):
        return state, -2.07 if len(s) > 1 else 0.0
    if not eligible:
        return state, 0.00204
    value = syllable_value(t, w, a, latin, cyrillic, punct, word, previous)
    return state, value

"""Approximate a text-output syntax detector, mainly negative at opening quotes.

Recognize print/log calls, input prompts, shell echo and C++ streams. Escaped
code, f-strings and tokens containing string contents get smaller pulses.
Also recognize bracketed log levels and the colon of an initial Title header.
Keep only a short text suffix, resetting it at each document boundary.
"""
import re

READS = ()
CALL = re.compile(
    r'\b(k?printf|print(?:ln|line)?|fprintf|sprintf|perror|format|'
    r'writeln|write(?:line)?|input|debug|log(?:f|error)?|'
    r'(?:console|logger|logging|k?log)\.(?:log|debug|info|warn|warning|'
    r'error|fatal|trace|[dveiw])f?|echo(?:\s+-[a-z]+)*)'
    r'\s*([!(\sfrb]*|\(stderr)$', re.I
)
STREAM = re.compile(r'\b(?:cout|cerr|clog)\b|\bLOG\([^)]*\)')
LOG_LEVEL = re.compile(r'(?:^|\n)\[(?:INFO|WARN|WARNING|ERROR|DEBUG|TRACE)$')


def quote_pulse(name, suffix, token):
    """Magnitude from the kind of output call and the opening delimiter."""
    opening = token.lstrip()
    # Most calls require a parenthesis; print/echo also have command syntax.
    command = name in ('print', 'printf') or name.startswith('echo')
    if not command and '(' not in suffix and not opening.startswith(('(', '!')):
        return 0.0
    if name == 'fprintf' and suffix == '(stderr':
        opening = opening.lstrip(',')
    opening = opening.lstrip('!(')
    if opening == 'f':
        if '(' not in token and '(' not in suffix:
            return 0.0
        return -0.7 if name == 'write' else -3.5
    if not opening:
        return -1.6 if token == '!(' else 0.0
    escaped = opening.startswith('\\')
    opening = opening.lstrip('\\')
    if not opening or opening[0] not in '\"\'`':
        return 0.0
    quote, content = opening[0], opening[1:]
    strength = 8.2 if quote == "'" else 7.4
    if name == 'console.log':
        strength = 8.9 if quote == "'" else 7.4
    elif 'log' in name or name == 'debug':
        strength *= 0.75
    if name == 'input':
        strength *= 0.8
    if name == 'writeln':
        strength *= 0.65
    if escaped:
        strength = 4.7 if name == 'print' else 5.2
    if 'f' in suffix:
        strength = 3.4 if escaped else 6.4
    elif '(' in suffix and '(' not in token:
        strength *= 0.8
    if name.startswith('echo'):
        strength = 2.3 if escaped else 6.6
    if name in ('perror', 'format', 'sprintf', 'write'):
        strength *= 0.2
    if name == 'fprintf':
        strength = 4.8
    if quote == '`':
        strength = 4.2 if token.startswith('(') else 0.0
    if content:
        # A token containing a whole small string is not an opening-only token.
        if quote in content:
            strength *= 0.2
        elif content.startswith('\\\\'):
            strength *= 0.4
        elif content.startswith(('[', ',', '.')):
            strength *= 0.35
        else:
            strength *= 0.65
    return -strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    match = CALL.search(tail)
    if match:
        name, suffix = match.groups()
        name = name.lower()
        # A request object's input(key) reads a field, not a console prompt.
        method_input = name == 'input' and tail[:match.start()].endswith(('.', '->'))
        if not method_input:
            value = quote_pulse(name, suffix, token)
    stream = None
    for candidate in STREAM.finditer(tail):
        stream = candidate
    if stream:
        opening = token.strip()
        attached = re.match(r'^[)\]]*<<\s*', opening)
        if attached:
            opening = opening[attached.end():]
        elif not tail.rstrip().endswith('<<'):
            opening = ''
        if opening.startswith(('"', "'")):
            # Later string fragments in a stream expression are weaker.
            strength = 3.0 if '"' in tail[stream.end():] else 7.0
            if len(opening) > 1:
                strength *= 0.5
            value = -strength
        elif opening == 'endl':
            value = -2.5
    # A split newline escape immediately after the opening quote.
    if token == 'n':
        before_quote = re.search(r'[\"\']\\+$', tail)
        if before_quote and CALL.search(tail[:before_quote.start()]):
            value = -3.7
    if token == ']' and LOG_LEVEL.search(tail):
        value = -4.2
    if token == ':' and tail.strip() == 'Title':
        value = 10.7
    tail = (tail + token).replace('\\n', '\n').replace('\\t', '\t')
    return (doc, tail[-120:]), float(value)

"""A short-r-fragment heuristic, plus conversation-boundary responses.

Arabic-script r fragments and r fragments following recent Turkish-style
letters get positive activation. Shorter fragments get more gain; recent
Persian-style letters reduce the Arabic-script gain. Tokens consisting
entirely of repeated r letters are negative. Other ordinary tokens are zero.
Separate constants handle chat markers and document starts. All history
resets at document boundaries. This omits token-specific lexical effects.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()
TURKISH_LETTERS = frozenset('ğışİĞŞ')
PERSIAN_LETTERS = frozenset('پچژگک')
MARKERS = {
    '</tool_call>': 1.57,
    '<tool_response>': 0.38,
    '</tool_response>': -0.52,
    '<think>': -1.04,
    '<tool_call>': -0.10,
    '<|im_end|>': -0.10,
}

@lru_cache(maxsize=32768)
def spelling(s):
    return anyascii(s).lower().strip()


def rhotic(s, turkish, persian):
    t = spelling(s)
    if not any(c in s for c in 'rRرрР') or len(t) > 5:
        return 0.0
    if len(t) >= 2 and set(t) == {'r'}:
        return -1.4
    if regex.search(r'\p{Script=Arabic}', s):
        if persian > 0.157:
            return 0.38
        if len(t) > 2:
            return 0.99
        if s[:1].isspace():
            return 1.10
        return 3.04 if t.endswith('r') else 1.85
    if turkish > 0.966:
        return 1.71 if len(t) <= 2 else 0.56
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    turkish, persian = (0.0, 0.0) if first else carry[1:]
    value = rhotic(s, turkish, persian)
    if s == '<|im_start|>':
        value = -0.536 if first else 0.37
    elif s in MARKERS:
        value = MARKERS[s]
    elif first:
        value = -0.20
    turkish = 0.97 * turkish + bool(TURKISH_LETTERS.intersection(s))
    persian = 0.97 * persian + bool(PERSIAN_LETTERS.intersection(s))
    return (doc, turkish, persian), float(value)

"""A partial spelling-based detector centred on 特 ('special/distinctive').

Bare 特 is strongest, except after common foreign-name syllables. Familiar
compounds give smaller responses, including selected second characters when a
compound is split. A few exceptional-quality and suddenness words respond too.
Korean 특 and Vietnamese đặc also respond positively.
Secondary rules cover Greek te, short consonant+et fragments, HTML table-row
names, middle-dot runs, and eight nonbreaking spaces. Everything else is zero.
Amplitudes are rounded training estimates, not a general semantic model.
"""
import re

READS = ()

# Chinese syllables often immediately before 特 in transliterated foreign names.
NAME_ENDINGS = frozenset(
    '阿艾埃奥奧安巴博伯贝貝布丹迪德杜尔爾弗伏盖蓋格古卡科克'
    '拉莱萊兰蘭雷里利莉罗羅洛鲁魯马馬麦麥密蒙摩纳納尼诺諾'
    '帕潘佩普萨薩塞森施斯塔泰坦特陶蒂图圖托维維沃温溫西希亚亞伊惠推底夫法奈'
)
SPECIAL_COMPOUNDS = {'特别', '特別', '特色', '特性', '特种', '优异'}
SMALLER_COMPOUNDS = {'特殊', '特殊的', '特定', '特意', '特派员', '特效'}
UNIQUE_COMPOUNDS = {'独特', '獨特', '独特的', '獨特的', '奇特', '奇特的'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, dots_only = b'', True
    else:
        tail, dots_only = carry[1:]
    before = tail.decode('utf-8', 'ignore')
    raw = tail + prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'ignore')
    new = text[len(before):]
    token = new.strip()
    # Joining bytes above completes characters split across token boundaries.
    leading_space = new[:len(new) - len(new.lstrip())]
    previous = (before + leading_space)[-1:]
    value = 0.0

    if token == '特':
        if previous in NAME_ENDINGS:
            value = 2.6
        elif re.search('[ぁ-ヿ]', before):
            value = 7.6
        else:
            value = 9.0
    elif token == '中国特色':
        value = 5.0
    elif token.endswith(('特点', '特點')):
        value = 2.6
    elif token in {'特征', '特徵', '特徴'}:
        value = 1.8
    elif token == '特有的':
        value = 4.0
    elif token in SPECIAL_COMPOUNDS:
        value = 2.9
    elif token in SMALLER_COMPOUNDS:
        value = 1.5
    elif token in UNIQUE_COMPOUNDS:
        value = 0.8
    elif previous == '特':
        if token in {'许', '地', '别', '色'}:
            value = 4.8
        elif token in {'大', '優', '有', '发', '發'}:
            value = 3.8
        elif token in {'写', '寫', '徵', '聘'}:
            value = 2.1
        elif token in {'許', '醫'}:
            value = 1.5
        elif token in {'典', '徴'}:
            value = 0.8
    elif token == '优':
        value = 1.7
    elif token in {'優', '突'}:
        value = 1.3
    elif token in {'突然', '优秀', '优质'}:
        value = 0.8
    elif token == '특':
        value = 6.1
    elif previous == '특' and token in {'이', '출'}:
        value = 3.5
    elif token.lower() == 'đặc':
        value = 3.9
    elif token in {'ε', 'έ'} and previous in {'τ', 'Τ'}:
        value = 3.6 if len(before) < 2 or not before[-2].isalpha() else 0.8
    elif token == 'τ' and re.search(r'(?:^|\W)[τΤ][εέ]$', before):
        value = 4.0
    elif token in {'et', 'ett', 'ET'}:
        # Short consonantal onsets before the letter fragment 'et'.
        match = re.search(r'[^\W\d_]+$', before)
        onset = match.group().lower() if match else ''
        if onset == 'ch':
            value = 2.8
        elif onset in {'t', 'd', 'st', 'z'}:
            value = 1.2
        elif onset and len(onset) <= 3 and onset.endswith(('t', 'd')):
            value = 0.35
        elif (onset and len(onset) <= 2 and not onset.isascii()
              and not any(c in 'aeiou' for c in onset)):
            value = 1.3
    elif (token in {'<tr', '</tr'}
          or token == 'tr' and before.endswith(('<', '</'))):
        value = -2.7 if token == '</tr' or before.endswith('</') else -4.0
    elif new == '··':
        value = -2.2 if dots_only else (-0.22 if before.endswith('··') else 0.0)
    elif new == '\xa0' * 8:
        spaces = len(before) - len(before.rstrip('\xa0'))
        value = 1.5 if spaces == 1 else 0.45 / (1 + max(0, spaces - 8) / 12)

    dots_only = dots_only and new != '' and not new.strip('·')
    return (doc, raw[-192:], dots_only), value

programs.haiku:
"""Predicts layers.1.mlp.down_proj:840, a component that responds to the Chinese character 特
("special", "characteristic") and to words built on it: 特别, 特色, 特殊, 特性, 特定, 中国特色,
and the Korean/Vietnamese equivalents. It is strongest on a standalone 特 (about 7) and weaker on
the compounds (about 2 to 5); the character right after a standalone 特 in 特许, 特地 and 特写 also
responds. A 特 inside a foreign-name transliteration (亚特兰大, 希特勒, 推特, 卡特) responds weakly
(about 2). Weaker responses come from other words for "distinctive or outstanding" (优异, 独特,
突出), and HTML table-row tags <tr> are negative. All predictions are multiplied by 0.3: at full
scale the predictions hurt the model more than switching the component off on the eval rows, and
scaling down trades variance explained for that. Only the previous and current token are read."""
READS = ()
SHRINK = 0.3

# 特 inside a foreign-name transliteration (亚特兰大, 希特勒, 推特, 卡特): little response.
NAME_SYLLABLES = {"亚", "希", "推", "卡", "科", "尼", "帕", "玛", "蒙", "伯", "尔", "蓋", "里",
                  "塞", "伊", "施", "斯", "罗", "瓦", "诺", "弗", "屈", "洛", "安"}
# Words built on 特 that keep its 'special' sense.
SPECIAL = {"特别": 3.0, "特別": 3.0, "特色": 2.8, "特殊": 2.2, "特性": 3.0, "特定": 1.5,
           "特有": 4.0, "中国特色": 5.0, "特征": 2.0, "特徵": 2.0, "特点": 2.4, " 특": 6.7,
           " đặc": 3.0, "특": 5.8}
# Other 'distinctive / outstanding' words: a weaker response.
DISTINCT = {"优": 1.7, "優": 1.0, "优秀": 0.6, "优异": 2.4, "突": 1.0, "突出": 0.7, "独特": 1.2,
            "奇": 0.8, "尤其": 0.4}
# The character right after a standalone 特 in 特许, 特地, 特大, 特异, 特写.
AFTER_TE = {"许": 4.5, "地": 4.5, "大": 3.0, "异": 3.8, "写": 2.0}

def activation(prefix):
    s = prefix.token_strings[-1]
    same = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same else ""
    if s == "特":
        return 2.0 if prev in NAME_SYLLABLES else 7.0
    if s in SPECIAL:
        return SPECIAL[s]
    if prev == "特" and s in AFTER_TE:
        return AFTER_TE[s]
    if s in DISTINCT:
        return DISTINCT[s]
    if s == "tr" and prev.strip() in ("<", "</"):
        return -2.5
    return 0.0

def step(carry, prefix, upstream):
    return None, SHRINK * activation(prefix)

programs.sol:
"""Approximate rare spikes on exact document-opening spellings.

The main high-importance pattern is initial 12, firing on its second digit.
Other positive openings are Title:, Hy + dro, <!, and (function + space + ().
The initial fragment " catal" is negative. NUL and uninterrupted runs of
certain divider tokens are handled separately. Case, spaces and token splits
matter: these are spelling rules, not topic detectors. Small background
activations are deliberately left at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, repeated = 0, token, True
    else:
        position = carry[1] + 1
        first = carry[2]
        repeated = carry[3] and token == first

    value = 0.0
    if position == 0:
        if token == ' catal':
            value = -2.25
        elif token == '\x00':
            value = 1.80
        elif token == '<!':
            value = 2.43
        elif token == 'Title':
            value = 0.92
        elif token == 'Hy':
            value = 0.69
    elif position == 1:
        if first == '1' and token == '2':
            value = 3.19
        elif first == 'Title' and token == ':':
            value = 3.26
        elif first == 'Hy' and token == 'dro':
            value = 3.98
