    elif stripped == 'part' and before.endswith('This file is'):
        value = 0.72
    elif stripped == 'of' and before.endswith('This file is part'):
        value = 0.25
    elif stripped == 'Level' and before.endswith(' Challenge'):
        value = -0.31
