READS = ()

PRONOUNS = set("i you he she it we they me him her us them".split())
POSSESSIVES = set(
    "my your his her its our their mine yours hers ours theirs".split()
)
PREPOSITIONS = set("in on at by from with within without upon".split())
# Articles, auxiliaries, conjunctions, demonstratives, and interrogatives.
FUNCTION_WORDS = set((
    "a an the am is are was were be been being do does did have has had "
    "can could may might must shall should will would "
    "and or but nor so yet if because although while unless "
    "this that these those who whom whose what which when where why how"
).split())


def initial_pulse(text):
    word = text.strip()
    lower = word.lower()
    if text.startswith('<|'):
        return 11.33 if text == '<|endoftext|>' else 3.47
    if not word:
        if text == ' ':
            return -1.62
        if text == '\t':
            return 8.49
        if '\n' in text or '\r' in text:
            return 2.52 if text.startswith(' ') else 4.72
        return 3.69
    if word.isdecimal():
        return 4.63

    # File-opening directives, comments, headings, and docstrings.
    if word.startswith('#include'):
        return 18.75
    if set(word) == {'#'}:
        return 14.65 if len(word) > 1 else 11.20
    if word.startswith('#!'):
        return 12.02
    if word.startswith('/*'):
        return 10.34
    if word in {'import', 'package'}:
        return 9.38
    if word == 'using':
        return 16.66
    if word in {'"""', "'''"}:
        return 13.14
    if word == '::':
        return 16.07
    if word in {'*', '•', '●'}:
        return 8.38
    if all(c in ',，、' for c in word):
        return -1.06
    if all(c in '.。…' for c in word):
        return 1.34
    if all(c in '()（）' for c in word):
        return -0.14
    if all(c in '\"\'“”‘’' for c in word):
        return 0.71
    if all(c in '|│' for c in word):
        return 6.34

    if word == 'I':
        return -2.21
    if lower in PRONOUNS and word != 'i':
        return 0.39 if text.startswith(' ') else -1.09
    if lower in POSSESSIVES:
        return 5.48
    if lower in PREPOSITIONS:
        return 10.65
    if lower in {'of', 'to', 'for'}:
        return 6.70
    if lower in FUNCTION_WORDS:
        return 2.30
    if word == 'Q':  # Conventional question label.
        return 13.86
    if word.isascii() and word.isalpha():
        if len(word) == 1 and word.isupper():
            return 1.04
        if word.istitle():
            return 4.62
        return 2.44 if text.startswith(' ') else 3.98
    return 3.64


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    value = initial_pulse(prefix.token_strings[-1]) if first else -0.0046
    return document, value

programs.haiku:
"""Layer 1, MLP down_proj, component 843: a document-opening detector.

What it does: outside the first token of a document this component is essentially silent
(its activation is about zero). A row of packed text is several documents end to end, and
the model resets attention at each change of document id, so the first token of every
document sees only itself. That first token is where the component fires, and how strongly
depends on what the opening word looks like, judged from the token's text alone:

  high (about 9 to 13): code and markup openers (#, ##, #include, /*, import, using,
           package); headings, page labels and instruction verbs that open web pages
           (Home, Title, Question, Use, Join, Browse, Install, Show, Start); prepositions
           that open a fragment (in, on, by, from, with, at)
  medium (about 4 to 7): digits, longer whole words, web addresses (www, http),
           newlines and indentation, chat special tokens, the, a, an, possessives
           (my, your, our), and longer capitalised or lower-case words
  low (about 0 to 3): leading-space word pieces that continue a sentence, short fragments,
           lone capital letters, and articles or conjunctions and auxiliaries (and, is, can)
  negative: prose sentence openers (I, He, She, It, They, We, There, Who) and a comma or a
           lone space (about -1.5 to -2)
  zero: every other position in a document, and invalid UTF-8 fragments

Values are the typical activation for each class, in the component's own units.
"""

READS = ()

IMPERATIVE = set("""use see join browse visit edit install review select choose buy download learn write read
start need get show add try take give make check click find know look go follow contact purchase
explore study fix enter sign view discover register create print open run set save load send call
apply help keep hold bring pick""".split())
UI_WORDS = set("""home title question name tag free welcome introduction category about translate
using import package include namespace require speaker math making preparing discussion description
news posted published test play public file showing provide used""".split())
WEB = set("www http https localhost".split()) | {"://", ".com", ".org", ".net"}
PREP = set("""in on at by with from into through between about of for under over after during across
among within via towards toward inside behind around beyond against without like upon onto""".split())
POSS = set("my your our its their her us his".split())
SUBJ = set("i he she it they we you there who".split())
FUNC = set("""and or but if as so not than then when because while also only no all some each every
many most other such this that these those is are was were be been can could would should will may
might must do does did has have had""".split())
PUNCT = set(',;:)(}{"\'') | {"“", "”", "，", "。"}
CODE = set("/*<[|\\$@%&^~>")


def value(s):
    """Typical activation for the first token of a document, given its text `s`."""
    if s == "" or "�" in s:
        return 0.0
    if s == " ":
        return -1.5
    b = s.strip().lower()
    if b == "":
        return 4.0                              # newlines, tabs, indentation
    if s.startswith("<|"):
        return 3.5                              # chat special tokens
    if b[0].isdigit():
        return 4.5
    if b[0] == "#" or b in ('"""', "/*", "/*\n", "::", "**"):
        return 13.0
    if b[0] in CODE:
        return 6.0
    if b[0] in PUNCT:
        return -1.5 if b[0] == "," else 0.0
    if b[0] == ".":
        return 1.0
    if b[0] in ":=+-":
        return 2.5
    if not b[0].isalpha():
        return 4.0
    if b in WEB or s in WEB:
        return 10.0
    if b in IMPERATIVE or b in UI_WORDS:
        return 12.0 if s[0] != " " else 7.5    # capitalised or bare-form verbs, headings
    if b == "to":
        return 6.0
    if b in PREP:
        return 9.0
    if b in POSS:
        return 5.0
    if b in SUBJ:
        return -2.0
    if b in ("the", "a", "an"):
        return 3.0
    if b in FUNC:
        return 1.5
    if s[0] == " ":
        return 2.3                              # mid-sentence word piece
    if len(s) == 1 and s.isupper():
        return 1.5
    if len(b) <= 3:
        return 3.0
    if len(b) == 4:
        return 4.3
    return 5.7 if len(b) <= 6 else 7.2          # longer whole words fire more


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, float(value(prefix.token_strings[t]))
    return None, 0.0

"""A closing brace that ends a block of code.

Keeps a stack of the braces opened so far in the document. A `{` that ends its
line (or follows a space or `)`) opens a code block; a `{` inside a formula,
subscript, or JSON-like literal does not. When a `}` closes a code block, it
fires strongly if it starts its own line (the usual end of a function, loop or
if), more strongly for short blocks, and weakly if it sits at the end of a line
of code.
"""

READS = ()


def opens_block(tok):
    body = tok.rstrip(" \t\r\n")
    breaks = len(body) < len(tok)
    if body.endswith("\\"):
        body, breaks = body[:-1], True
    if not body.endswith("{"):
        return False
    before = body[:-1]
    return breaks or before[-1:] in (" ", "\t", ")")


def is_closer(tok):
    return tok.strip(" \t\r\n\\") == "}"


def line_close_value(lines):
    # short blocks (a few lines) close more strongly than long ones
    if lines <= 4:
        return 6.0
    if lines <= 16:
        return 5.0
    return 4.0


def step(carry, prefix, upstream):
    if carry is None or carry["doc"] != prefix.document_ids[-1]:
        carry = {"doc": prefix.document_ids[-1], "stack": [], "line_start": True, "lines": 0}
    tok = prefix.token_strings[-1]
    stack = carry["stack"]
    value = 0.0
    if is_closer(tok):
        if not stack:
            value = 3.5 if carry["line_start"] else 0.0
        elif stack[-1][0]:
            if carry["line_start"]:
                value = line_close_value(carry["lines"] - stack[-1][1])
            else:
                value = 2.0
        if stack:
            stack.pop()
    else:
        for ch in tok:
            if ch == "{":
                stack.append((opens_block(tok), carry["lines"]))
            elif ch == "}" and stack:
                stack.pop()
    carry["lines"] += tok.count("\n")
    if "\n" in tok:
        carry["line_start"] = tok.rsplit("\n", 1)[1].strip() == ""
    elif carry["line_start"]:
        carry["line_start"] = tok.strip() == ""
    return carry, value

programs.sol:
"""A sparse recognizer for local code and link idioms.

Most tokens get zero. Positive exceptions include GitHub URLs, JavaScript
exports, double-underscore metadata, and a few standard API expressions.
Call/signature names, test-failure markers, C++ std:: and middle-dot
typography get negative values. Numbers are approximate activation sizes.
Only the current and preceding token are used; documents are independent.
"""
READS = ()


def predict(previous, token):
    word = previous.strip()
    if previous.endswith('://') and token == 'github':
        return 5.1
    if word == 'export' and token == ' default':
        return 5.8
    if token == '.exports':
        return 3.6
    if word == 'Object':
        if token == '.keys':
            return 4.1
        if token == '.entries':
            return 3.3
        if token == '.defineProperty':
            return 1.85
    if word == 'Array' and token in {'.from', '.isArray'}:
        return 2.0
    if word == '---' and token == ' FAIL':
        return -1.8
    if word == 'std' and token == '::':
        return -0.42
    if previous.endswith('[#') and token == 'permalink':
        return 3.4

    if previous.endswith('__') and token.isascii() and token.isalpha():
        # Export lists and module/object metadata, rather than ordinary names.
        if token == 'all':
            return 12.5 if previous == '__' else 10.0
        if token == 'author':
            return 9.8
        if token == 'esModule':
            return 7.5
        if token == 'slots':
            return 3.3 if "'" in previous or '"' in previous else 6.2
        if token == 'dirname':
            return 5.4
        if token in {'class', 'future'}:
            return 3.4
        if token == 'del':
            return 2.6
        if token in {'getattr', 'repr', 'enter'}:
            return 2.0
        if token in {'call', 'invoke', 'args'}:
            return -2.8
        if token in {'init', 'main'}:
            return 0.1
        if token == 'tests':
            return 1.0
        return 0.6 if len(token) == 1 else 0.3

    if previous.endswith('_') and token == 'id':
        return 4.8
    if word.lower() == 'auto' and token.lower() == '_increment':
        return 4.8 if token.isupper() else 2.7
    if previous.endswith('.add') and token == '_argument':
        return 1.3
    if word == 'max' and token == '_age':
        return 1.0
    if previous.endswith('%') and token == 'w':
        return 1.9  # Go's error-wrapping format verb.
    if word == 'eslint' and token == '-disable':
        return 3.3
    if token == '··':
        return -0.825
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), predict(previous, token)

programs.haiku:
"""Sparse identifier and URL triggers: a handful of code and web tokens that fire strongly
in their usual context. Everything else is treated as silent (0).

Each rule names a token and the token right before it; the value is the typical
activation there. Groups: web links, JS/CommonJS exports, Python/JS dunder names,
underscore-id keys, SQL AUTO_INCREMENT, and Object.keys/values/entries.
"""
READS = ()

# Dunder names (the word between a leading and trailing "__"), with typical activation.
DUNDER = {"all": 10.0, "author": 10.0, "esModule": 9.0, "slots": 6.5, "dict": 6.0,
          "dirname": 5.5, "class": 4.0, "generator": 4.0, "future": 3.5, "router": 1.8,
          "tests": 1.2, "getattr": 2.5, "del": 3.0, "origin": 1.5}
OBJECT_HELPERS = {".keys", ".values", ".entries"}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2:
        return carry, 0.0
    cur, prev = toks[-1], toks[-2].strip()
    if cur == "github" and prev == "://":
        return carry, 5.0          # https://github... domain name
    if cur == " default" and prev == "export":
        return carry, 6.0          # export default
    if cur == ".exports" and prev == "module":
        return carry, 4.0          # module.exports
    if cur == "permalink" and prev == "[#":
        return carry, 3.3          # markdown heading anchor
    if cur in ("_INCREMENT", "_increment") and prev in ("AUTO", "auto"):
        return carry, 4.0          # SQL AUTO_INCREMENT
    if cur == "id" and prev.endswith("_"):
        return carry, 5.0          # _id keys
    if cur in OBJECT_HELPERS and prev in ("Object", "Array"):
        return carry, 3.9          # Object.keys(...) and friends
    if prev.endswith("__") and cur in DUNDER:
        return carry, DUNDER[cur]  # __all__, __author__, __dirname__ ...
    return carry, 0.0

