"""Approximate stability/consistency responses and their spelling false friends.

Stable/stability, 稳/穩, and 'with' in consistency or continuity expressions
receive negative values. Separately, split spellings around st/ст have strong
responses: completing stab- is negative, but stash-, staph-, and stroll- are
positive. These spelling rules do not assert that the words share a meaning.
Other uses of with get a small positive baseline, as do middle-dot runs.
Other cases get zero. An 80-character tail and the previous token are remembered,
and reset at document boundaries.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=65536)
def spelling(s):
    return s.strip().lower(), anyascii(s).strip().lower()


def response(s, tail, previous):
    w, a = spelling(s)
    if w in ('稳', '穩'):
        return -5.0
    if w in ('稳定', '穩定'):
        return -2.2
    if re.fullmatch(r'(un)?stable', w):
        return -2.8 if w.startswith('un') else -3.7
    if re.fullmatch(r'(in)?stabilit(y|ies)', w):
        return -3.8 if w.startswith('in') else -3.0
    if w.endswith('stab'):
        return -3.8
    if w.endswith('stabil'):
        return -1.0
    if w == 'estable':
        return -1.0
    if w == 'steady':
        return -0.3
    if a.startswith('stash'):
        return 3.3
    if a.startswith('starch'):
        return 1.5
    if a == 'stol':  # Russian стол: table, or start of столица (capital).
        return 1.9
    if len(s) >= 2 and set(s) == {'·'}:
        return 0.79

    if w == 'with':
        words = re.findall(r'[a-z]+', tail.lower())
        last = words[-1] if words else ''
        if last == 'consistent':
            return -4.4
        if last == 'inconsistent':
            return -2.8
        if last == 'keeping':
            return -10.5
        if re.search(r'\bin[- ]line\s*$', tail.lower()):
            return -3.9
        if last in ('stick', 'sticking', 'stuck', 'stay', 'staying'):
            return -3.3
        if re.search(r'\b(keep|keeping|kept) up\s*$', tail.lower()):
            return -3.0
        if last in ('accordance', 'compatible', 'concordant', 'compliance'):
            return -1.5
        if re.search(r'\bin agreement\s*$', tail.lower()):
            return -2.7
        if last in ('consistency', 'congruent', 'fit', 'fits'):
            return -2.1
        if re.fullmatch(r'align(s|ed|ing)?', last):
            return -1.8
        return 0.04
    if w in ('line', 'step') and re.search(r'\bin\s*$', tail.lower()):
        return -1.4

    # Token-spanning spellings; transliteration also handles Cyrillic ст.
    p = spelling(previous)[1]
    if not s or not s[0].isalpha():
        return 0.0
    if p.endswith(('st', 'sht')):
        if a.startswith('aph'):
            return 2.5
        if a.startswith(('ash', 'ax')):
            return 3.9
        if a.startswith('ab'):
            return -6.2 if a.startswith(('able', 'abil')) else -4.0
        if a.startswith('alt'):
            return 1.3 if a.startswith('alten') else 0.0
        if a == 'al' and p.endswith('dist'):
            return -4.0
        if w.startswith('ав'):
            return -3.0
        if a.startswith('al') and len(a) <= 4:
            return -2.4
        if a == 'av' or a == 'ad':
            return -1.8
        if a.startswith('ag'):
            return -4.5 if s.strip().isupper() else -1.0
        if a in ('a', 'as', 'ac', 'and'):
            return -1.4
        if a.startswith('roll'):
            return 4.5
        if a.startswith(('ubs', 'ump')):
            return 2.3
        if w == 'ол':
            return 1.9
