        return 2.3
    if p.endswith('ste') and a.startswith('ad'):
        return -2.3
    if p.endswith('stab') and a.startswith('ili'):
        return -3.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    s = prefix.token_strings[-1]
    value = response(s, tail, previous)
    return (doc, (tail + s)[-80:], s), value

