    if s in ('wet', 'wit', 'twe', 'swe', 'zwe', 'vet', 'ven', 'vens'):
        return -0.40
    if (continuation and old.endswith(('св', 'Св', 'в', 'В'))
            and current.startswith(('я', 'ят', 'ящ', 'ет', 'ит'))):
        return -0.26
    if (continuation and old.endswith('ス')
            and current.startswith(('イ', 'ィ', 'エ'))):
        return -4.19
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(previous, token)
    return (doc, (previous + token)[-32:]), value

"""Sparse spelling and byte-fragment approximation.

Only repeatable surface triggers are modeled, not one shared semantic topic.

Negative responses mark psi (especially mathematical psi), weaker phi/xi/chi,
'finger'/'singer', and fragments completing -inger or -ing+en/er endings.
Capitalized prefixes and Schrödinger get stronger negative responses.
Positive responses mark standalone 言 and 언, ng+ay, and middle-dot runs.
For space-prefixed CJK characters split into bytes, the separately arriving
second byte is negative for the UTF-8 prefix of 水, positive for that of 言.
These are literal encoding rules, not assertions about character meanings.
Most positions return zero; small background activations remain unmodeled.
"""
import re

READS = ()
PHI = tuple(c.encode() for c in 'φϕΦ')
WEAK_GREEK = tuple(c.encode() for c in 'ξΞχΧ')


def word_at_end(text):
    match = re.search(r'[^\W\d_]+$', text)
    return match[0] if match else ''


def activation(previous, token):
    joined = previous + token
    s = token.decode('utf-8', 'ignore')
    low = s.lower().strip()
    if joined.endswith('Ψ'.encode()):
        return -8.3
    if joined.endswith('ψ'.encode()):
        return -4.9
    if joined.endswith(b'\\Psi') and len(token) <= 3:
        return -7.2
    if low == 'psi':
        return -6.0 if previous.endswith(b'\\') else -1.4
    if joined.endswith(PHI) or low == 'phi':
        return -0.55
    # Some space-prefixed CJK characters split after their first byte.
    # Respond at the separately tokenized second byte, before completion.
    if len(token) == 1:
        if joined.endswith(b' ' + '水'.encode()[:2]):
            return -4.0
        if joined.endswith(b' ' + '言'.encode()[:2]):
            return 3.2
    if joined.endswith(WEAK_GREEK) or low == 'xi':
        return -0.15
    # Only isolated characters or their final byte fragments, not compounds.
    for character, value in (('言', 2.2), ('언', 1.8)):
        encoded = character.encode()
        if token == encoded or (len(token) < 3 and joined.endswith(encoded)):
            return value
    if s == 'ay' and previous.endswith((b'ng', b'Ng')):
        return 3.9
    if len(s) > 1 and not s.strip('·'):
        return 0.55 if previous.endswith('·'.encode()) else 0.0
    if len(low) < 2 or not s[-1].isalpha():
        return 0.0

    text = joined.decode('utf-8', 'ignore')
    whole = word_at_end(text)
    stem = whole.lower().removesuffix('s')
    if stem == 'finger':
        return -1.9 if whole[0].isupper() else -0.6
    if stem == 'singer':
        return -1.4 if whole[0].isupper() else -1.0
    if low in ('inger', 'er') and re.search(
        r'schr[^\s]{0,8}dinger$', text.lower()
    ):
        return -12.4

    prior = word_at_end(previous.decode('utf-8', 'ignore'))
    capital = bool(prior and prior[0].isupper())
    if low == 'inger':
        if s.strip().isupper():
            return -8.0
        return -5.8 if capital else -2.8
    if low == 'ingen':
        return -1.3
    if capital and s == low and re.fullmatch(r'[a-z]+ingers?', low):
        return -4.4
    # These endings must be attached fragments, not space-led whole words.
    if s == low:
        if low in ('er', 'ers', 'en'):
            if prior.lower().endswith('ing'):
                return -5.8 if capital and low == 'en' else -2.9
            if prior.lower().endswith('ng'):
                return -0.66
        if low in ('ton', 'ly') and prior.lower().endswith('ing'):
            return -1.8 if capital else -0.18
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else b''
    token = prefix.token_bytes[-1]
    value = activation(previous, token)
    return (document, (previous + token)[-80:]), value

"""Approximate selected noun-phrase endings, not nouns in general.

Rules cover age groups, institutions, and technical-object labels. WordNet
adds artifact names qualified by relational adjectives. English heads must
arrive as complete tokens; listed Chinese compounds must straddle tokens.
Unlisted phrases get zero. Document starts and repeated middle dots have
separate offsets. The short text buffer resets at document boundaries.
"""
import re
from functools import lru_cache
import wordnet
from opencc import OpenCC

SIMPLIFY = OpenCC('t2s')

READS = ()

@lru_cache(maxsize=16384)
def phrase_value(modifier, head):
    # Age descriptions of groups of people.
    if modifier == 'young':
        if head == 'people':
            return 1.4
        if head in {'adult', 'adults'}:
            return 0.75
        if 'noun.person' in wordnet.categories(head, 'noun'):
            return 0.25
    if modifier in {'older', 'elderly'} and head in {'adult', 'adults'}:
        return 1.1
    if modifier == 'pregnant' and head in {'woman', 'women'}:
        return 0.55

    # Institutions, their personnel, and public services.
    bases = wordnet.base_forms(head, 'noun')
    singular = bases[-1] if bases else head
    if singular == 'government':
        if modifier == 'local':
            return 1.25 if head.endswith('s') else 2.0
        if modifier in {'city', 'county', 'municipal'}:
            return 1.0
        if modifier in {'federal', 'state', 'central', 'national'}:
            return 0.65
    if singular == 'court':
        if modifier == 'circuit':
            return 1.6
        if modifier in {'district', 'public'}:
            return 0.75
    if modifier == 'public':
        if singular == 'library' or head == 'libraries':
            return 1.9
        if singular in {'school', 'servant', 'official', 'good', 'debt'}:
            return 1.2
        if head in {'policy', 'facilities', 'institution', 'institutions'}:
            return 0.85
    if singular == 'school' and modifier in {'primary', 'secondary', 'elementary'}:
        return 0.65
    if singular == 'student' and modifier in {
        'school', 'college', 'graduate', 'undergraduate'
    }:
        return 1.25 if modifier == 'college' else 0.65
    if singular == 'official' and modifier in {'elected', 'government'}:
        return 0.9
    if singular == 'council' and modifier == 'city':
        return 0.75
    if singular == 'organization' and modifier in {
        'nonprofit', 'non-profit', 'charitable'
    }:
        return 0.55
    if modifier == 'developing' and head in {'country', 'countries'}:
        return 0.5

    # Familiar technical and everyday compounds.
    if singular == 'phone' and modifier in {'cell', 'mobile'}:
        return 2.2 if head.endswith('s') else 2.65
    if modifier == 'atomic' and singular == 'bomb':
        return 2.0
    if modifier == 'secondary' and head in {'battery', 'batteries'}:
        return 1.9
    if modifier in {'electric', 'motor'} and singular in {
        'motor', 'vehicle', 'car', 'guitar', 'current', 'charge'
    }:
        return 0.85
    if singular == 'device' and modifier in {
        'mobile', 'electronic', 'connected', 'telecommunications'
    }:
        return 0.9
    if modifier in {'video', 'mobile'} and singular == 'game':
        return 0.75
    if modifier == 'traffic' and singular == 'light':
        return 0.75
    categories = wordnet.categories(modifier + ' ' + head, 'noun')
    if 'noun.artifact' in categories:
        if singular in {'vehicle', 'car', 'truck'}:
            return 0.6
