        senses = wordnet.categories(modifier)
        if 'adj.pert' in senses and 'noun' not in wordnet.parts_of_speech(modifier):
            if 'noun.group' not in wordnet.categories(head, 'noun'):
                return 0.65
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    text = '' if first else carry[1]
    token = prefix.token_strings[-1]
    text = (text + token)[-80:]
    value = 0.0
    if first:
        if token.strip().isdigit():
            value = 0.09
        elif not token.isspace():
            value = -0.13 if token.startswith(' ') else -0.21
    if (not first and token and set(token) == {'·'}
            and text.endswith('····')):
        value = 0.615
    elif token and not token[-1].isascii():
        # The same public-institution and technical-object families in Chinese.
        chinese = SIMPLIFY.convert(text)
        token_length = len(SIMPLIFY.convert(token))
        compounds = (
            (r'(?:电动|机动|动力)(?:汽)?车(?:辆)?$', 1.7),
            (r'(?:电子设备|锂离子电池)$', 1.3),
            (r'(?:公办|公立)(?:学校|医院|医疗机构)$', 1.7),
            (r'(?:公司债|公债|中小企业)$', 1.8),
            (r'(?:公文|规范性文件)$', 2.1),
        )
        for pattern, amplitude in compounds:
            match = re.search(pattern, chinese)
            if match and len(match[0]) > token_length:
                value = amplitude
                break
