            value = phrase_value(words[1].lower(), words[2].lower())
    return (document, text), float(value)

"""Dotted notation and the boundaries of identifying descriptions.

Keep a short document-local text tail. Distinguish decimal/version dots from
numbered list markers and repeated dots within an already fractional number.
Titles, initials and conventional abbreviations also receive a positive
response. Katakana and Han name-separating middle dots are distinguished from
bullets; repeated middle dots get a small negative value. Name suffixes Jr and
Roman numerals get a positive value. Articles after copulas, especially after
biographical dates, mark identifying descriptions. Parentheses and appositive
articles following multiword title-cased names get smaller positive values.
A row/document-initial "Title:" field also gets a strong response. Other tokens receive zero.
"""
import regex as re

READS = ()
TITLES = set(
    'Mr Mrs Ms Dr Prof Rev Hon St Mme Mlle Sr Sra Fr '
    'Col Lt Gen Capt Sgt Maj Gov Pres Supt'.split()
)
REFERENCES = set(
    'no nos fig figs eq eqs vol pp cf al etc vs approx ca pat ch sec sect '
    'art ref cir ct app supp hist univ inst dist fed stat ser ed'.split()
)
MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
MATH_LABEL = re.compile(
    r'(?:point|vertex|triangle|circle|line|plane|angle|variable|set|matrix|'
    r'vector|center|centre|node|label|option|case|part|section|appendix)\s+$',
    re.I,
)


def dot_value(text):
    match = re.search(r'(\d+)$', text)
    if match:
        number = match[0]
        before = text[:-len(number)]
        line = before.rsplit('\n', 1)[-1]
        decimals = bool(re.search(r'\d[.]\d', before[-180:]))
        if before.endswith('.'):
            return 0.0
        if not line.strip(' >*#\\') or re.search(r'\\n\s*$', before):
            return (0.48 if number == '0' else 0.25) if decimals else -0.04
        if len(number) == 4 and 1600 <= int(number) <= 2099:
            return 0.04
        if len(number) == 1:
            return 0.96 if decimals else (0.78 if number == '0' else 0.5)
        return 0.7 if decimals else 0.3
    match = re.search(r'([\p{Latin}\p{Cyrillic}\p{Greek}]+)$', text)
    if not match:
        return 0.0
    word = match[0]
    if word in TITLES:
        return 1.25 if word == 'St' else 0.95
    if word == 'v':
        return 0.95
    if word.lower() in MONTHS:
        return 0.6
    if word.lower() in REFERENCES:
        return 0.45
    if len(word) == 1:
        before = text[:-1]
        start = not before.rsplit('\n', 1)[-1].strip(' >*#\\')
        if MATH_LABEL.search(before):
            return 0.05
        if word.isupper():
            # Early alphabet letters are also common outline/diagram labels.
            outline_letter = word in 'ABCDEF'
            if start:
                return 0.15 if outline_letter else 0.9
            if name_strength(before.rstrip()):
                return 1.25
            return 0.6 if outline_letter else 1.0
        return 0.05 if start else 0.3
    if len(word) <= 4 and word.isupper():
        return 0.3
    return 0.0


# A lexical name heuristic, not a person dictionary: title-cased words at the
# right edge, excluding pronouns and common organizational heads.
NOT_NAMES = set(
    'I He She It They We You This That There Here What Which Who These Those '
    'The A An His Her Their Our Your My Its Each One Some Such All Any '
    'University College School Institute Department Ministry State City County '
    'Province District Government Council Act Order Court Church Hospital '
    'Services Party League Bank Club'.lower().split()
)
NAME_TAIL = re.compile(
    r"(\p{Lu}\p{Ll}[\p{L}'’-]*(?: "
    r"(?:\p{Lu}\p{Ll}[\p{L}'’-]*|\p{Lu}\.))*)$"
)


def name_strength(text):
    match = NAME_TAIL.search(text)
    if not match or match[0].split()[-1].lower() in NOT_NAMES:
        return 0
    return 1 + (len(match[0].split()) >= 2)


def identity_article(text):
    match = re.search(r'\b(?:is|was|are|were)\s*$', text)
    if not match:
        return 0.3 if text.endswith(',') and name_strength(text[:-1]) == 2 else 0.0
    subject = text[:match.start()].rstrip()
    aside = re.search(r'\([^)]*\)$', subject)
    if aside:
        return 0.8 if re.search(r'\d{4}|born|died', aside[0]) else 0.45
    strength = name_strength(subject)
    return 0.45 if strength == 2 else (0.37 if strength else 0.05)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '.':
        value = dot_value(text)
    elif token == ' (' and name_strength(text.rstrip()) == 2:
        value = 0.2
    elif token in (' a', ' an'):
        value = identity_article(text)
    elif token in (' is', ' was') and re.search(
        r'\([^)]*(?:\d{4}|born|died)[^)]*\)$', text
    ):
        value = 0.42
    elif token == ':' and text == 'Title':
        value = 3.12
    elif token == '.,':
        value = 0.18 * (dot_value(text) > 0.1)
    elif token in ('·', '・'):
        if re.search(r'\p{scx=Katakana}$', text):
            value = 1.0
        elif token == '·' and re.search(r'\p{Script=Han}$', text):
            value = 0.0 if text.rfind('《') > text.rfind('》') else 2.1
    elif len(token) > 1 and set(token) == {'·'}:
        value = -0.3
    elif token.strip() == 'Jr':
        value = 1.05
    elif re.fullmatch(r' [IVX]{2,5}', token):
        value = 0.3
    return (doc, (text + token)[-256:]), value

programs.haiku:
"""Layer 1, MLP down-projection component 851: a "decimal point / abbreviation period" detector.

It is nearly silent everywhere except on a period token ("."), and on a middle dot "·"
in a transliterated foreign name. The period fires when it is NOT an ordinary sentence end:
  - a decimal point in a number ("1.5", "0.01", "v1.0", "($2.50"): strong after 0 or 1,
    weaker otherwise; zero for list numbers at the start of a line ("\\n2.") and for
    years (4+ digits, usually a sentence end);
  - a period after a person's title ("Mr.", "Dr.", "St.", "Mrs.") or after a single capital
    initial ("Michael L."): strong;
  - other short capitalised abbreviations ("No.", "Fig."): weak.
A period after an ordinary lower-case word (the end of a sentence) gives 0.
"""
READS = ()

DIGITS = set("0123456789")
TITLES = {"Mr", "Mrs", "Ms", "Dr", "St", "Prof", "Sr", "Jr", "Col", "Gen", "Rev"}
OPENERS = {"(", "$", "≈", "__", "=", "v", "["}


def is_number(text):
    return text != "" and all(c in DIGITS for c in text)


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    if t == 0:
        return None, 0.0
    if s[t] == "·":
        return None, 1.0  # middle dot inside a transliterated name
    if s[t] != ".":
        return None, 0.0
    prev = s[t - 1].strip()
    if is_number(prev):
        # walk back over the whole number to the token just before it
        i = t - 1
        while i >= 0 and is_number(s[i].strip()):
            i -= 1
        if i < 0 or "\n" in s[i]:
            return None, 0.0  # list numbering at the start of a line
        if t - 1 - i >= 4:
            return None, 0.1  # a year, usually a sentence end
        if s[i].strip() in OPENERS:
            return None, 1.0  # "(1.5", "$2.50", "v1.0"
        return None, 0.7 if prev in ("0", "1") else 0.5
    if prev in TITLES:
        return None, 1.0  # "Mr.", "Dr.", "St."
    if len(prev) == 1 and prev.isupper():
        return None, 1.0 if s[t - 1].startswith(" ") else 0.4  # initial: "Michael L."
    if prev[:1].isupper() and len(prev) <= 3:
        return None, 0.4  # other short capitalised abbreviation
    return None, 0.0

programs.sol:
"""Approximate boundaries where a variable is spliced into literal text.

Negative responses mark resumed string literals (concatenation), and the
closing delimiters of interpolation fields and bracketed placeholders.
Longer alphabetic fields generally receive a stronger response.  A colon
immediately following document-initial 'Title' has a separate positive pulse.
Minor rules cover printf, environment variables, macro pasting, and JSON
string endings. Only a short text tail is retained; documents reset state.
"""
import re

READS = ()
QUOTES = '\"\'`'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, text, prev, position = carry
    s = prefix.token_strings[-1]
    p = prev.strip()
    head = s.lstrip().lstrip('\\')
    value = 0.0

    if s == ':' and position == 1 and prev == 'Title':
        value = 8.66
    elif head.startswith(tuple(QUOTES)):
        if prev == ' +':
            literal = text[:-len(prev)].rstrip().endswith(tuple(QUOTES))
            if literal:
                value = -0.3
            else:
                value = -7.6 if head[0] == '"' else -5.0
        elif prev == ' .' and '$' in text[-160:]:
            value = -7.0
        elif p == '<<':
            line = text.rsplit('\n', 1)[-1]
            value = -5.7 if line.count('<<') > 1 else -1.7
        elif p == '+':
            value = -1.5
        elif p == '+=':
            value = -2.7
    elif re.match(r'^\s*[()\[\]]*(?:\+|<<)\s*[\"\'`]', s):
        value = -5.4
    elif re.match(r'^\([\"\'`]', s):
        if p.lstrip('.').lower() in {'append', 'concat'}:
            value = -2.5
        elif p.lstrip('.').lower() == 'join':
            value = -0.8

    close = re.match(r'^[()\[\]]*}', s)
    if close and not any(c in s for c in '\n\r;'):
        opening = text.rfind('{')
        field = text[opening + 1:] + s[:s.index('}')]
        before = text[:opening]
        letters = sum(c.isalpha() for c in field)
        expression = re.sub(r'^(?:typeof|await) ', '', field)
        clean = (0 < len(expression) <= 60 and
                 not re.search(r'[{}\s;=]', expression))
        math = re.search(r'\\(?:frac|sqrt|left|right|begin)|\$\$',
                         text[-160:])
        math = math or re.search(r'\\[a-zA-Z]+$', before)
        line = before.rsplit('\n', 1)[-1]
        quoted = any(line.count(q) % 2 for q in QUOTES)
        template = (quoted or before.endswith('$') or
                    re.search(r'(?:f|\$)[\\]*["\']', before[-100:]) or
                    before.endswith(tuple(QUOTES)))
        if opening >= 0 and clean and letters > 1 and not math:
            if field.startswith('@'):
                value = -0.9
            elif template:
                value = -min(6.5, 1.0 + 0.36 * letters)
                if s[s.index('}') + 1:].startswith(tuple(QUOTES)):
                    value *= 0.2
            else:
                value = -0.6

    if s.startswith(']'):
        opening = text.rfind('[')
        field = text[opening + 1:] if opening >= 0 else ''
        if 0 < len(field) <= 30 and re.fullmatch(r'[\w .’\'-]+', field):
            if re.fullmatch(r'[A-Za-z]+(?: [A-Za-z]+)* [Nn]ame', field):
                value = -5.5
            elif re.match(r'(?:Your|your|Insert|insert) ', field):
                value = -2.0
            elif p.isalpha() and len(p) > 3:
                value = -0.3

    if any(c in s for c in '\n\r') and any(q in s for q in QUOTES):
        value *= 0.2

    if s == '%' and p.isupper() and len(p) > 2:
        value = -min(6.0, 0.7 * len(p))
    if s == '##' and p.isidentifier():
        value = -min(3.5, 0.4 * len(p))
    if s == 's' and prev.rstrip().endswith('%'):
        value = -1.1
    if s.startswith('"}}'):
        value = -0.30
    return (doc, (text + s)[-400:], s, position + 1), value

"""A sparse spelling response, not a general French-language detector.

Positive cues are French third-person pronouns and subword completions such
as eil/euil, elle, eux and ouv/euv. Some u/ew continuations are negative.
French word frequency strengthens the ambiguous eil cue. Most tokens get
zero; repeated middle dots have a small negative response. State retains
only the current word's tail and resets between documents.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
PRONOUNS = {}
for forms, value in (
    ('il ils', 0.08), ('elle elles', 1.89), ('lui', 1.36),
    ('leur leurs', 0.50), ('eux', 1.51),
    ('celui celle celles ceux', 2.87),
):
    PRONOUNS.update(dict.fromkeys(forms.split(), value))
L_SYLLABLE = re.compile(r'ils?|ill(?:e[szr]?|y|é[es]*)?\Z')
WORD_TAIL = re.compile(r'[^\W\d_]+\Z')


@lru_cache(maxsize=8192)
def french_advantage(word):
    # An unfinished -ill stem can be checked as an -iller infinitive.
    words = (word, word + 'er') if word.endswith('ill') else (word,)
    advantage = max(zipf_frequency(w, 'fr') - zipf_frequency(w, 'en')
                    for w in words)
    return max(-2.0, min(3.0, advantage))


def response(before, token):
    s = token.lower()
    word = s.lstrip(" \t\n'’-")
    boundary = word != s or not before
    value = 0.0
    if boundary:
        value = PRONOUNS.get(word, 0.0)
        if re.fullmatch(r'(?:qu|t)el(?:le)?s?', word):
            value += 0.58
        if word in PRONOUNS and s.startswith(("'", '’')):
            value += 1.17
    if s in (' sue', 'sue', ' suing', ' sued'):
        value -= 1.62 + (2.17 if 'S' in token else 0.0)
    if s.startswith('ew') and before.endswith(('th', 'ph', 'sh', 'wh')):
        value -= 1.52
    if token == '··':
        value -= 0.77
    if boundary:
        return value

    if L_SYLLABLE.fullmatch(s):
        if before.endswith('e'):
            value += 2.85 + 0.89 * french_advantage(before + s)
        if before.endswith(('eu', 'ou', 'œ', 'oe')):
            value += 4.94
        elif before.endswith('u'):
            value += 1.23
        if s in ('il', 'ils') and before.endswith('out'):
            value += 2.97
    if s.startswith('uil') and before.endswith('e'):
        value += 6.27
    if s.startswith('ueil'):
