                value += 0.78 + (2.59 if before.endswith('œ') else 0.0)
        elif s.startswith('ud'):
            value += 0.56 + (3.03 if before.endswith(('oe', 'œ')) else 0.0)
        elif re.fullmatch(r'us{1,2}|um|uß', s):
            value -= 1.85
        elif s in ('use', 'uses'):
            value += 0.95
