        value -= 0.59
        if before.endswith('s') and not before.endswith('ss'):
            value -= 2.87
    if before.endswith('sp') and s.startswith(('ou', 'ew', 'he')):
        value -= 2.02
        if s.startswith(('ew', 'ous')):
