"""Word-internal French "-il" fragments, scaled by how French the recent text is."""
import re

READS = ()

FRENCH_WORDS = set(
    "le la les de des du un une et est qui que dans en pour sur avec au aux il elle ils elles "
    "son sa ses ce cette ces sont été être ne pas plus mais ou donc nous vous leur".split()
)
IL_FRAGMENT = re.compile(r"[a-zàâçéèêëîïôûùüÿœæ]*(?:ueil|eil|uil|ille|illes|ill|il|ux)")
PRONOUN = {"ils", "elle", "elles", "lui", "celle", "celui", "celles", "ceux"}


def french_share(prefix, window=15):
    """Share of the last `window` words, within this document, that are French function words."""
    words = []
    doc = prefix.document_ids[-1]
    for i in range(len(prefix.token_ids) - 1, -1, -1):
        if prefix.document_ids[i] != doc:
            break
        words.extend(re.findall(r"[^\W\d_]+", prefix.token_strings[i].lower()))
        if len(words) >= window:
            break
    words = words[:window]
    if not words:
        return 0.0
    return sum(w in FRENCH_WORDS for w in words) / len(words)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    french = french_share(prefix)
    value = 0.0
    if token[:1] != " " and IL_FRAGMENT.fullmatch(token):
        value = 3.0 * french
    elif token.strip() in PRONOUN:
        value = 3.0 * french
    return carry, value

