"""A local spelling detector for short 'ju/yu' fragments, not a phonetic parser.

Negative responses cover ju/yu, Latin -ius, Cyrillic ю, Japanese yu,
and Arabic y+w. Splitting a glide and u across tokens also counts;
short i-fragments after j/y instead get positive values. Common complete
words are attenuated. Cyrillic ю can leave a response on its next fragment.
Small calibrations cover document starts, doubled middle dots, and an
incomplete word-initial Cyrillic byte. Only the previous token is retained.
"""
from functools import lru_cache
import calendar
import unicodedata
from wordfreq import zipf_frequency
from anyascii import anyascii

READS = ()
MONTHS = frozenset(calendar.month_abbr[1:])

@lru_cache(maxsize=65536)
def predict(previous, token, first):
    text = token.decode('utf-8', 'ignore')
    before = previous.decode('utf-8', 'ignore')
    # Complete a Cyrillic character split between two byte tokens.
    if token and 128 <= token[0] < 192:
        joined = (previous[-4:] + token).decode('utf-8', 'ignore')
        text = joined[-len(text)-1:]
    s = text.strip()
    lower = s.lower()
    last = before[-1:].lower()
    value = -0.16 if first else 0.0
    if token == b' \xd1':
        return -2.1
    if s == '··':
        return -1.1
    if lower.endswith('ius') and len(s) <= 4:
        return -3.4
    if lower == 'iu':
        return -1.0
    if lower.startswith(('ju', 'yu')) and s.isalpha() and len(s) <= 5:
        if len(s) == 2:
            return -2.0 if s[0].isupper() and text[:1].isspace() else -3.0
        if s in MONTHS:
            return -0.3
        if not s.isascii() or (len(s) >= 4 and any(
                zipf_frequency(lower, lang) >= 3.9
                for lang in ('fr', 'es', 'pt', 'pl', 'id'))):
            return 0.0
        if any(ch.isupper() for ch in s[1:]) and not s.isupper():
            return 0.0
        frequency = zipf_frequency(lower, 'en')
        rarity = max(0.0, min(1.0, (4.5 - frequency) / 1.5))
        return -3.2 * rarity * (0.5 if len(s) == 5 else 1.0)
    if 'ю' in lower and len(s) <= 3:
        if lower == 'ю':
            if text[:1].isspace() or not before or before[-1:].isspace():
                return -10.0 if token[:1] == b'\x8e' else -7.0
            if last in 'аеёиіоуыэяєьй':
                return -0.7 if last != 'о' else -1.3
            return -2.0 if last in 'лн' else -4.0
        if lower in ('лю', 'люб', 'юр'):
            return -2.3
        if lower == 'ью':
            return -0.7
    if len(s) == 1 and anyascii(s).lower() == 'yu':
        name = unicodedata.name(s, '')
        if name.startswith(('HIRAGANA', 'KATAKANA')):
            return -2.8
    if s == 'يو':
        return -2.3
    if before.endswith('ي') and text.startswith('و') and len(s) <= 2:
        return -4.0
    if text[:1].isalpha() and last == 'ю' and len(s) <= 2:
        if before.strip().lower() == 'ю' or (
                before[:1].isspace() and before.strip().lower() == 'лю'):
            return -4.4 if len(s) == 1 else -2.0
    if text[:1].isalpha() and last in ('i', 'j', 'y'):
        if text[0].isupper() and before[-1:].islower():
            return 0.0
        base = unicodedata.normalize('NFD', text[0].lower())[0]
        if base == 'u' and len(s) <= 4:
            # The ur/ure spelling is stronger after a bare glide.
            if lower == 'ur':
                return -6.0
            if lower == 'ure':
                return -6.0 if len(before.strip()) == 1 else -3.0
            if last == 'j' and text[0].lower() != 'u':
                if len(s) > 1:
                    return -2.5
                marks = unicodedata.normalize('NFD', text[0])
                return -7.0 if '\u0304' in marks else -4.5
            if last in ('j', 'y') and lower[1:] in ('s', 'ss', 'sh', 'sz'):
                return -5.8
            if len(s) == 2 and s[1].lower() in 'aeiou':
                return -0.5
            if last == 'j':
                if len(s) <= 2:
                    return -4.3
                return -2.6 if len(s) == 3 else -0.6
            if last == 'i':
                if len(s) == 1:
                    return -1.1
                return -3.2 if len(s) == 2 else -1.4
            return -1.7
        if last == 'j' and lower in ('ah', 'eh', 'oh'):
            return -3.0
        if last in ('j', 'y') and text[0].lower() == 'i' and 2 <= len(s) <= 4:
            if last == 'j':
                return 1.6
            return 0.2 if lower in ('in', 'ing') else 1.5
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    value = predict(previous, token, not previous)
    return (doc, token), value

programs.haiku:
"""Layer-1 MLP neuron 854 (down_proj component 854): a sparse, context-driven feature.

Simple readable version, from the spelling of the word being written:
  * the first token of each document (inside a packed row) is pushed negative;
  * inside a word spelled with a leading J (Juan, Jūrmala, Julia...), a piece with a
    u-sound ('u', 'ū', 'ju', 'jug', 'ura') is strongly negative, a piece with an i-sound
    ('ik', 'ikes', 'ir') is mildly positive, other pieces are mildly negative;
  * bare 'ju'/'iu'/'ius'/'uc'-type fragments (foreign names, split Cyrillic 'ю') are negative.
Everything else is predicted as 0.
"""
import re

READS = ()

DOC_START = -0.17
J_U = -0.28
J_I = 0.16
J_OTHER = -0.06
FRAGMENT = -1.4
FRAG = re.compile(r"^(ju|iu|yu|ius|uc|uri|ure|uer|juan|jug|jud|jur)$")


def step(carry, prefix, upstream):
    # carry: letters of the word being spelled so far
    word = carry or ""
    raw = prefix.token_strings[-1]
    piece = raw.strip().lower()
    doc_start = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start or raw[:1].isspace():
        word = ""
    for ch in raw.lstrip():
        word = word + ch if ch.isalpha() else ""
    if doc_start:
        return word, DOC_START
    value = 0.0
    if word[:1].lower() == "j":
        if "u" in piece or "ū" in piece or "ü" in piece:
            value = J_U
        elif "i" in piece:
            value = J_I
        else:
            value = J_OTHER
    if not raw.startswith(" ") and FRAG.match(piece):
        value = FRAGMENT
    return word, float(value)

