"""Approximate a negative response to r plus a front-vowel ending.

The strongest rule is for short pieces completing -ery/-ry/-rie-like
spellings. Count doubled r once and the y/ie-family ending as one unit for
this short-piece test. Longer, familiar whole words mostly have weak
responses; less-common capitalized double-r forms are stronger. Katakana
ri/rii and Cyrillic r plus the soft sign extend this to two other scripts.
State retains a bounded current word and the previous token, resetting at
document boundaries. A final 0.8 scale makes the approximation conservative.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=8192)
def familiarity(word):
    return zipf_frequency(word, 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    oldword = '' if first else carry[1]
    previous = '' if first else carry[2]
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+$', oldword + token)
    word = match[0][-128:] if match else ''
    state = (doc, word, token)
    low = word.lower()
    ending = re.search(r'r(y[stc]*|ie|ies|ied|i|e|ia)$', low)
    value = -0.063 if first else 0.0014

    if token == 'リー':
        value = -4.28
    elif token == 'リ':
        value = -0.94
    elif token.lower() == 'ь' and previous.lower().endswith('р'):
        value = -1.5
    elif ending and re.search(r'[A-Za-z]$', token):
        tail = ending[1]
        ree = tail.startswith('y') or tail.startswith('ie')
        piece = re.search(r'[A-Za-z]+$', token)[0]
        rpos = low.rfind('r')
        before = low[rpos-1] if rpos else ''
        doubled = before == 'r'
        if doubled:
            cluster = re.search(r'([a-z])r+$', low[:rpos+1])
            before = cluster[1] if cluster else ''
        sound_length = (len(piece) - len(tail) + 1
                        - int('rr' in piece.lower()))
        continued = bool(token[0].isalpha() and oldword)
        freq = familiarity(low)

        if token.strip().lower() == 'ery':
            value = -4.6
        elif not continued:
            if doubled:
                if freq <= 4.27:
                    value = -4.2 if token.strip().istitle() else -2.17
                else:
                    value = -0.05
            elif not ree:
                value = -0.006
            elif freq > 3.34:
                value = -0.10
            else:
                value = -1.78 if len(word) <= 3 else -0.57
        elif not ree or sound_length > 4:
            value = -0.10
        elif before == 'e':
            value = -4.24
        elif before == 'a':
            value = -0.63
        elif before in 'roui':
            value = -2.27
        else:
            value = -1.41
    return state, float(0.8 * value)

"""A local detector for reporting code: logs, exceptions and printed messages.

The main cue is an opening string argument of a diagnostic/output routine.
Formatted diagnostics are strongest; ordinary printing is weaker. Escaped
source snippets get a smaller response. Reporting vocabulary also responds
without a string argument. Only a short suffix within the document is used.
"""
import re
READS = ()

LEVELS = {'trace', 'debug', 'info', 'warn', 'warning', 'error', 'fatal', 'panic'}
LOGGERS = {'log', 'logger', 'logging', 'klog', 'slog', 'glog', 'alog', 'debug'}
PRINT = {'print', 'printf', 'println', 'fprintf', 'puts', 'echo', 'writeline'}
STREAMS = {'cout', 'cerr', 'clog', 'stdout', 'stderr'}
NAME = re.compile(r'([\w$.:]+)\s*!?\s*$')
CALL = re.compile(r'([\w$.:]+)\s*!?\(+\s*([^()]*)$')
QUOTE = re.compile(r'^[!(,=]*(?:fr|rf|f|r)?["\x27`]')
MESSAGE = {'formatted diagnostic': 9.5, 'logging': 6.3, 'exception': 5.6,
           'error printing': 4.5, 'formatted printing': 3.8, 'printing': 2.5,
           'formatting': 1.1, 'notification': 4.0, 'assertion': 3.5,
           'other': 0.01}


def routine(name, args=''):
    parts = name.lower().replace('::', '.').split('.')
    last, receiver = parts[-1], parts[-2] if len(parts) > 1 else ''
    if last.endswith('f') and last[:-1] in LEVELS | {'log'}:
        return 'formatted diagnostic'
    if receiver in LOGGERS or receiver.endswith('logger'):
        return 'logging'
    if receiver == 'console' and last in LEVELS:
        return 'logging'
    if last in {'log', 'debug'} or name.endswith(('Log', 'Debug')):
        return 'logging' if receiver != 'console' else 'printing'
    if re.search(r'(?:^|_)(?:TRACE|DEBUG|LOG)\d*$', name):
        return 'logging'
    if last in {'perr', 'perror'}:
        return 'error printing'
    if 'error' in name.lower() or 'exception' in name.lower():
        return 'exception'
    if last in {'fatal', 'panic', 'die', 'abort', 'unreachable', 'fail', 'expect', 'failwith'}:
        return 'exception'
    if last in {'sprintf', 'format'}:
        return 'formatting'
    if last.endswith('printf'):
        return 'formatted printing'
    if last in PRINT or last.endswith('println'):
        return 'printing'
    if last in {'write', 'send', 'log'} and receiver in STREAMS | {'console'}:
        return 'printing'
    if last.lstrip('_').startswith('assert') and ',' in args:
        if not re.search(r'equal|_eq|_ne', last) or args.count(',') >= 2:
            return 'assertion'
    if last in {'alert', 'prompt', 'notify'} or last.endswith('alert'):
        return 'notification'
    return 'other'


def message(previous, clean):
    before = previous.replace('\\n', '\n').replace('\\t', '\t')
    before = re.sub(r'(?m)^[ +\-]*\d+\t', '', before)
    before = re.sub(r'\n[+\-]', '\n', before).rstrip()
    if clean.startswith(('(', '!(')):
        match = NAME.search(before)
        return routine(match[1]) if match else 'other'
    if before.endswith('+'):
        return 'other'  # continuation of a concatenated literal
    match = CALL.search(before)
    if match:
        args, quote = match[2].replace('\\', ''), ''
        depth = 0
        for char in args:
            if not quote and char in '[{':
                depth += 1
            elif not quote and char in ']}':
                depth -= 1
            if char in '\"\x27`':
                quote = '' if quote == char else char if not quote else quote
        if depth > 0:
            return 'other'  # data nested inside an object/array, not a message
        if quote and clean.count(quote) < 2:
            return 'other'  # closing the old message, not opening a new one
        return routine(match[1], args)
    match = NAME.search(before)
    if match and match[1].lower() in {'echo', 'throw'}:
        return 'printing' if match[1].lower() == 'echo' else 'exception'
    if before.endswith('<<') and re.search(r'\b(?:cout|cerr|clog|LOG)\b', before):
        return 'printing'
    if re.search(r'\bassert\b[^\n]*,\s*$', before):
        return 'assertion'
    return 'other'


def predict(previous, text):
    stripped = text.strip()
    word = stripped.lstrip('._(').lower()
    clean = stripped.replace('\\', '')
    if QUOTE.match(clean) or stripped == '(f':
        literal = clean.lstrip('!(,=')
        if literal.startswith(('""', "''", '``')):
            return 0.0  # an empty string is not a message
        value = MESSAGE[message(previous, clean)]
        return value * (0.5 if '\\' in text else 1.0)
    if stripped == 'f':
        match = NAME.search(previous.rstrip())
        if match and match[1].lower().split('.')[-1] in LEVELS:
            return 9.3  # formatted logging suffix, as in Warn + f
    if word in LEVELS or (word.endswith('f') and word[:-1] in LEVELS):
        source = (previous + stripped).replace('?.', '.')
        source = source.replace('\\n', '\n').replace('\\t', '\t')
        match = NAME.search(source)
        if stripped.startswith('.') or previous.endswith('.'):
            kind = routine(match[1]) if match else 'other'
            parts = match[1].lower().split('.') if match else []
            logger = len(parts) > 1 and parts[-2] in LOGGERS
            if kind == 'logging' or logger:
                return 2.7 if word == 'trace' else 5.7
            return 3.0 if word.endswith('f') else 1.2
        if word in {'info', 'trace'}:
            return 0.0
        return 0.4 if word == 'error' and text[:1].isspace() and stripped.islower() else 1.2
    if word in {'err', 'errors', 'warnings', 'exceptions'}:
        return 0.9 if word == 'err' else 0.35
    if word in {'perror', 'perr'}:
        return 2.0
    if word.endswith(('error', 'exception')):
        return 0.8
    if word in PRINT:
        return 2.2 if word == 'echo' or stripped == '.println' else 1.0
    if word in STREAMS:
        return 3.0 if stripped.startswith('(') else 1.1
    if word in LOGGERS | {'fmt', 'console'}:
        return 1.4 if stripped.startswith('.') else 1.2 if word == 'logger' else 0.45
    if word in {'msg', 'message', 'messages'}:
        return 1.2 if word == 'msg' else 0.6
    if word in {'throw', 'raise'}:
        return 1.0
    if word == 'return':
        return 0.55 if '\t' in text else 0.18
    return 1.0 if stripped in {'❌', '✗'} else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, (previous + text)[-160:]), predict(previous, text)

"""Approximate document openings and formatted line boundaries.

Openings usually get a positive pulse. Within a document, indentation uses
its width and the preceding punctuation, with an extra transient over the
first few dozen tokens. Shallow control-flow exits get negative pulses.
Middle-dot leaders, the colon in a document-initial "Title:" label, and
hard-space/backtick markup have separate responses. Ordinary interior text is predicted as zero.
"""
import math

READS = ()
EXITS = {'return', 'break', 'continue', 'goto', 'yield'}
BRANCHES = {'if', 'for', 'while', 'else', 'try', 'except', 'switch', 'case'}


def opening(s):
    t = s.strip()
    if s.isspace():
        if '\n' in s or '\t' in s:
            return 0.9
        return 0.0 if len(s) == 1 else 0.15 if len(s) <= 3 else 1.1
    if t and t[0] in ',;)]}':
        return 0.2
    if t.lower() in {'is', 'are', 'was', 'were', 'be', 'been'}:
        return 0.05
    if t.isdigit():
        return 0.65
    if t.lower() in {'a', 'an'}:
        return 0.85
    if t.lower() in {'and', 'or', 'but'}:
        return 0.0
    if t in {'def', 'class', 'package', 'int', 'float', 'double'}:
        return 1.15
    if s.startswith(('#!', "'''", '"""')):
        return 1.4
    return 0.5 + 0.1 * bool(t and t[0].isupper()) - 0.2 * s.startswith(' ')


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, line, prev = 0, '', ''
    else:
        _, pos, line, prev = carry
    t = s.strip()
    at_start = not line
    indented = bool(line) and line.isspace()
    # Include whitespace attached to the current token; count a tab as four.
    leading = s[:len(s) - len(s.lstrip(' \t'))]
    indent = len(line + leading) + 3 * (line + leading).count('\t')
    value = 0.0
    if pos == 0:
        value = opening(s)
    elif pos == 1 and s == ':' and prev == 'Title':
        value = -10.1
    elif len(t) >= 2 and set(t) == {'·'}:
        value = 1.48
    elif s == '``' and len(line) - len(line.rstrip('\xa0')) >= 3:
        hard_spaces = len(line) - len(line.rstrip('\xa0'))
        if hard_spaces < 8:
            value = -1.15
        elif hard_spaces < 16:
            value = -0.2
    elif s == '\xa0' and prev.rstrip().endswith(('–', '—')):
        value = -0.65
    elif s.isspace() and at_start:
        before = prev.rstrip()[-1:]
        early = math.exp(-pos / 20.0)
        if '\t' in s:
            value = -0.5 if '\n' in s else 0.12 + 0.8 * early
        elif '\n' not in s:
            if len(s) <= 3:
                if before in {'{', '(', '['}:
                    value = -0.3
                elif before == ':':
                    value = -0.18
                else:
                    value = -0.04
                value -= 0.6 * early
            else:
                value = min(0.5, 0.016 * len(s) - 0.012)
                if before in {'{', '(', '['}:
                    value -= 0.15
                elif before == ':':
                    value -= 0.13
                value += 0.8 * early
    elif (at_start or indented) and t in EXITS | BRANCHES:
        if t == 'return':
            if indent == 0:
                value = -0.35
            elif indent <= 5:
                value = -2.2 + 0.15 * indent
            elif indent <= 9:
                value = -0.27
        elif t == 'break':
            value = -0.4 if indent == 0 else -max(0.4, 1.8 - 0.09 * indent)
        elif t == 'goto':
            value = -0.45 if indent <= 4 else -0.3
        elif t in {'continue', 'yield'}:
            value = -0.2
        else:
            value = -0.35 if 0 < indent <= 5 else -0.02
    elif (at_start or indented) and t in {'private', 'def'}:
        value = 0.4 if t == 'private' or indent > 0 else 0.03
    elif (at_start or indented) and t in {'public', 'protected', 'class'}:
        value = 0.13
    elif at_start and t and set(t) == {'#'}:
        value = 0.08
    elif s == '<|endoftext|>' and at_start:
        value = 0.4
    line = (line + s).split('\n')[-1][-256:]
    return (doc, pos + 1, line, s), float(value)

"""Approximate a detector of the written vowel pairs ui and uy.

Find the pair in the current or previous token, or across their boundary;
an older token supplies spelling context. Remove combining accents and
ignore case. Calibrated rules use neighboring consonants, suffix length,
and token boundaries; longer token pieces usually get a weak response.
A separate rule gives repeated middle dots a negative activation.
State is reset at document boundaries. Other responses are not modeled.
"""
import re
import unicodedata

READS = ()


def plain(text):
    return "".join(c for c in unicodedata.normalize("NFD", text.lower())
                   if not unicodedata.combining(c))


def response(older, previous, current):
    if len(current) >= 2 and set(current) == {"·"}:
        return -3.0
    older = plain(older)
    p = older + plain(previous)
    text = p + plain(current)
    matches = list(re.finditer("u[iy]", text))
    if not matches:
        return 0.0
    match = matches[-1]
    start, end = match.span()
    if start < len(older):
        return 0.0
    boundary = len(p)
    if end <= boundary and (not current or not current[0].isalpha()):
        return 0.0
    after = text[end:]
    if any(not c.isalpha() for c in after):
        return 0.0
    word = re.search("[a-z]+$", text[:start])
    stem = word.group() if word else ""
    lead = stem[-1:] or " "
    length = len(current.strip())
    if length > 4:
        return 0.066
    if lead == "t":
        if after.startswith("t"):
            return 7.066
        if end <= boundary:
            return 0.071
        return 3.985 if after.startswith("d") else 1.662
    if lead == "g":
        return -0.188
    if lead == "q":
        return 0.029

    # A vowel pair split between two tokens.
    if start < boundary < end:
        if after.startswith("n"):
            return 0.368
        if text[start + 1] == "y":
            return 0.773
        if len(after) <= 1:
            return 4.436
        if after.startswith("t"):
            return 3.345
        return 3.398 if lead == "l" else 1.513
    if lead == "b":
        return 0.088

    # Vowel pairs wholly inside a token, or their immediate continuation.
    if len(after) > 1:
        if lead == "n":
            return 4.686 if len(stem) <= 3 else 0.021
        return 0.350
    if not after or after[0] in "aeiou":
        return 1.304 if length <= 2 else 0.468
    if length <= 3:
        if after.startswith("d"):
            return 4.109
        return 4.774 if lead == "n" else 1.869
    return 2.540 if lead == "p" else 1.099


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        older, previous = "", ""
    else:
        _, older, previous = carry
    current = prefix.token_strings[-1]
    value = response(older, previous, current)
    return (doc, previous, current), value

"""A shallow English light-verb construction detector.

Positive rules cover subjective states ("have no idea", "a sense of"),
understanding, opinions and effects with their prepositional complements.
Arithmetic/extent heads after an indefinite article, and arithmetic "of"
complements, get negative values. Rules share weights across named noun
classes. Six preceding tokens supply the light-verb context; this is not
a full grammatical parser, and unrecognized constructions predict zero.
"""
from functools import lru_cache
import wordnet

READS = ()

# Head words in related light-verb and complement constructions.
CLASSES = {
    'subjective': set((
        'idea sense feeling notion impression intuition hunch clue'
    ).split()),
    'understanding': set((
        'knowledge understanding insight awareness comprehension '
        'familiarity expertise'
    ).split()),
    'opinion': set((
        'view perspective opinion outlook thought belief attitude'
    ).split()),
    'introduction': set((
        'overview introduction preview snapshot summary outline tour '
        'glimpse peek'
    ).split()),
    'effect': set((
        'effect impact influence bearing consequence repercussion '
        'implication'
    ).split()),
    'interest': set((
        'interest passion desire enthusiasm appetite taste tolerance '
        'preference hope wish'
    ).split()),
    'experience': set((
        'experience background training practice education exposure'
    ).split()),
    'control': set((
        'control authority power command sway dominion'
    ).split()),
    'grasp': set((
        'handle hold grip grasp hang'
    ).split()),
    'attempt': set((
        'go try shot stab attempt'
    ).split()),
    'perception': set((
        'look picture eye ear sight voice vision'
    ).split()),
    'relation': set((
        'relationship connection link bond tie'
    ).split()),
    'entitlement': set((
        'right claim access responsibility duty obligation'
    ).split()),
    'role': set((
        'role part say stake hand place seat'
    ).split()),
    'arithmetic': set((
        'sum product difference ratio quotient power square cube root'
    ).split()),
    'extent': set((
        'total maximum minimum limit distance angle radius length height '
        'width volume amount'
    ).split()),
}

# Noun-head contributions, selected by the surrounding construction.
HEAD_RULES = {
    'head': {
        'experience': 0.15,
    },
    'article': {
        'extent': -0.41,
        'arithmetic': -0.618,
        'perception': 1.004,
        'subjective': 1.406,
        'attempt': 1.291,
    },
    'have': {
        'effect': 0.809,
        'interest': 0.916,
        'subjective': 1.667,
    },
    'lightverb': {
        'understanding': 0.953,
        'grasp': 0.974,
        'introduction': 1.304,
        'subjective': 1.662,
    },
    'negative': {
        'effect': 1.17,
        'subjective': 1.819,
    },
    'determiner': {
        'grasp': 0.762,
    },
    'immediate_lightverb': {
        'subjective': -1.49,
    },
}

# (preposition, recent verb context) -> contribution by preceding head.
COMPLEMENTS = {
    ('of', 'always'): {
        'arithmetic': -0.434,
        'understanding': 1.175,
        'opinion': 0.396,
        'subjective': 0.884,
        'introduction': 0.655,
    },
    ('on', 'always'): {
        'effect': 0.883,
        'grasp': 1.519,
        'opinion': 1.95,
    },
    ('on', 'have'): {
        'effect': 1.764,
    },
    ('in', 'always'): {
        'role': 0.476,
    },
    ('in', 'have'): {
        'interest': 1.209,
    },
    ('to', 'have'): {
        'entitlement': 0.825,
    },
    ('with', 'have'): {
        'relation': 1.823,
    },
    ('over', 'always'): {
        'control': 0.989,
    },
    ('of', 'lightverb'): {
        'subjective': 2.354,
    },
    ('at', 'always'): {
        'attempt': 1.286,
    },
    ('of', 'have'): {
        'subjective': 2.007,
    },
    ('into', 'always'): {
        'understanding': 3.472,
    },
    ('at', 'lightverb'): {
        'perception': 1.053,
    },
}

LIGHT_VERBS = set("give get take make provide gain offer show find obtain".split())
DETERMINERS = set((
    "a an the any some no much more little less such this that each every "
    "his her its their our my your"
).split())


@lru_cache(maxsize=16384)
def classify(word):
    if not (word.isascii() and word.isalpha()):
        return (), word in {"'ve", "’ve"}, False
    nouns = {word, *wordnet.base_forms(word, 'noun')}
    verbs = set(wordnet.base_forms(word, 'verb'))
    classes = tuple(k for k, words in CLASSES.items() if nouns & words)
    return classes, 'have' in verbs, bool(verbs & LIGHT_VERBS)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else []
    word = prefix.token_strings[-1].strip().lower()
    previous = recent[-1] if recent else ''
    classes = classify(word)[0]
    contexts = {
        'always': True,
        'head': True,
        'article': previous in {'a', 'an'},
        'negative': previous in {'no', 'any'},
        'determiner': previous in DETERMINERS,
        'have': any(classify(w)[1] for w in recent),
        'lightverb': any(classify(w)[2] for w in recent),
        'immediate_lightverb': classify(previous)[2],
    }
    value = sum(weight for context, weights in HEAD_RULES.items()
                if contexts[context] for c, weight in weights.items()
                if c in classes)
    previous_classes = classify(previous)[0]
    value += sum(weight for (prep, context), weights in COMPLEMENTS.items()
                 if word == prep and contexts[context]
                 for c, weight in weights.items() if c in previous_classes)
    if word in {"'s", '’s'}:
        value -= 0.060
        if any(w in {'a', 'an'} for w in recent[-3:]):
            value += 0.762
    if word == 'to' and previous == 'as':
        value += 0.636
    if word == 'with' and previous == 'do':
        value += 1.680
    return (doc, (recent + [word])[-6:]), float(value)

"""A conservative, partial approximation of an omission/layout-marker signal.

Ellipses are negative, especially in test output and web-result snippets.
Middle dots following dates and dashes in repeated page headings are related
layout cues.  The literal navigation heading 'Events & Promotions' is another
strong response.  Strengths are halved because these cues also occur where the
component is weak.  Context is bounded and resets at document boundaries.
"""
import re

READS = ()
ELLIPSES = {'...', '....', '.....', ',...', '…'}
LINE_NUMBER = re.compile(r'\(line \d+\)$')
TEST_LINE = re.compile(r'(?:^|\n)test [^\n]+$')
YEAR_END = re.compile(
    r'\b(?:19|20)\d{2}(?:[-/]\d{1,2}){0,2}[\s\ufffd]*$'
)
COURSE = re.compile(r'phys|math|lecture|midterm|solution|homework', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, dots = '', '', 0
    else:
        _, previous, tail, dots = carry
    text = prefix.token_strings[-1]
    bare = text.strip()
    prev = previous.rstrip()
    value = 0.002

    if bare in ELLIPSES:
        value = -0.45 if text.startswith(' ') else -0.2
        if prev.endswith('/'):
            value = -0.6
        elif previous.isspace() or (prev and prev[-1] in '=([{:+'):
            value = -0.08
        elif LINE_NUMBER.search(tail):
            value = -1.3 if dots == 0 else -2.5
        elif TEST_LINE.search(tail):
            value = -0.2 if dots == 0 else -1.3
        elif text.startswith(' '):
            web_results = (
                'Web Results' in tail or 'Get Price' in tail
                or 'Get price' in tail or 'Presentation Summary' in tail
                or tail.count('http') >= 2 or tail.count('www.') >= 2
            )
            if web_results:
                value = -2.7
            elif prev.endswith('.'):
                value = -1.1
        if text == ' ...':
            dots += 1
    elif bare and set(bare) == {'·'}:
        if len(bare) > 1:
            value = -0.28
        elif YEAR_END.search(tail):
            value = -2.6 if '\xa0' in previous or '�' in previous else -1.1
        elif prev.endswith('.'):
            value = -0.8
        else:
            value = 0.08
    elif text == ' -':
        lines = tail.split('\n')
        line = lines[-1]
        title = line.lstrip('# ').strip()
        repeated = title and any(title == s.strip() for s in lines[:-1])
        if repeated and line.lstrip().startswith('#'):
            value = -2.4
        elif COURSE.search(line):
            value = -0.65
        elif line.lstrip().startswith('#'):
            value = -0.25
    elif (tail + text).endswith('Events & Promotions'):
        value = -3.2
    elif text == 'amp' and prev.endswith('&'):
        value = -0.68

    return (doc, text, (tail + text)[-600:], dots), 0.5 * value

"""A local comparison-complement detector.

Predict negative pulses on the second `as` in equality constructions,
`same/similar ... as`, and `than` after comparative phrases.
Boundary idioms are weaker; negation strengthens descriptive equalities.
The rules also cover European comparison markers and measurement `of`.
Ordinary uses mostly stay near zero. These grammatical heuristics are
not a full parser.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
LINKS = {' as', ' than', ' of', ' que', ' qu', ' che', ' como', ' come',
         ' als', ' wie', ' чем', ' как'}
DEGREE = {'more', 'less', 'fewer'}
DIMENSIONS = set('size length width height depth weight speed distance age '
                 'price volume frequency complexity severity'.split())
BOUNDARY = {'high', 'low', 'short', 'little', 'few', 'small', 'simple',
            'most', 'least'}
IDIOMS = {'well': -0.8, 'long': -1.5, 'far': -1.5,
          'early': -4.3, 'soon': -0.65}


@lru_cache(maxsize=8192)
def comparative(word):
    if word in DEGREE or word in {'better', 'worse'}:
        return True
    return word.endswith('er') and any(
        len(base) < len(word)
        for base in wordnet.base_forms(word, 'adjective'))


@lru_cache(maxsize=8192)
def descriptive(word):
    # Avoid dictionary senses like the adjective "in" (fashionable).
    function_words = {'in', 'on', 'as', 'no', 'any', 'either', 'every',
                      'all', 'some', 'part', 'mean', 'already', 'ever',
                      'such', 'that', 'this'}
    return (len(word) > 1 and word not in function_words and
            bool(wordnet.parts_of_speech(word) & {'adjective', 'adverb'}))


def after(words, cue):
    """Words following the last occurrence of a cue known to be present."""
    return words[len(words) - words[::-1].index(cue):]


def equality(words, text):
    last = words[-1] if words else ''
    for cue in ('same', 'similar'):
        if cue in words[-9:]:
            tail = after(words, cue)
            verbs = {'is', 'are', 'be', 'was', 'were', 'shall', 'can',
                     'has', 'have', 'does'}
            if not set(tail) & verbs:
                return -1.5 if not tail else -5.8
    if 'as' in words[-10:]:
        tail = after(words, 'as')
        if tail:
            first = tail[0]
            cues = [m for m in re.finditer(r'[^\W\d_]+', text)
                    if m.group() == 'as']
            before = text[:cues[-1].start()] if cues else ''
            negated = bool(re.search(
                r"\b(?:not|never|hardly)\b|n['’]t\b", before[-50:]))
            if first in IDIOMS and (first != 'well' or len(tail) == 1):
                return IDIOMS[first]
            if first in BOUNDARY:
                return -4.0
            if first in {'many', 'much'} and not set(tail) & {
                    'for', 'to', 'is', 'are'}:
                return -9.0
            if descriptive(first) and 'a' in tail[1:3] and len(tail) <= 6:
                return -11.0 if negated else -6.0
            # Descriptive phrases can include a participle or coordination.
            modifiers = all(descriptive(w) or w == 'and' or
                            'verb' in wordnet.parts_of_speech(w)
                            for w in tail[1:])
            if descriptive(first) and len(tail) <= 4 and modifiers:
                return -13.0 if negated else -9.0
    if last in {'well', 'long', 'far', 'soon'}:
        return IDIOMS[last]
    if 'so' in words[-6:]:
        tail = after(words, 'so')
        if tail and descriptive(tail[0]):
            return -2.5
    if ('such' in words[-5:] and last != 'such' and
            'as' not in words[-4:]):
        return -1.8
    return 0.08


def estimate(token, text):
    if token not in LINKS:
        return 0.0
    boundary = r'[.!?;:]|\n\s*\n'
    if token == ' as':
        boundary = r'[.,!?;:]|\n\s*\n'
    text = re.split(boundary, text.lower())[-1]
    words = re.findall(r'[^\W\d_]+', text)[-14:]
    last = words[-1] if words else ''
    recent = set(words[-10:])
    if token == ' as':
        return equality(words, text)
    if token == ' than':
        if last == 'rather':
            return 0.0
        if last in {'more', 'less', 'greater', 'other'}:
            return -0.5
        if comparative(last):
            return -3.0
        return -4.2 if any(comparative(w) for w in recent) else -0.5
    if token in {' que', ' qu', ' che', ' como', ' come'}:
        if recent & {'plus', 'aussi', 'moins'}:
            return -7.0
        if recent & {'más', 'mas', 'mais', 'menos', 'même', 'mêmes',
                     'tel', 'tels', 'telles', 'tão', 'tan', 'così', 'più',
                     'menor', 'mayor', 'mejor', 'peor', 'mismo', 'misma'}:
            return -3.0
        if token == ' che' and last == 'tanto':
            return 2.0
        return -0.65 if token in {' que', ' qu'} else 0.0
    if token == ' als':
        if recent & {'mehr', 'weniger'} and last not in {'mehr', 'weniger'}:
            return -5.0
        return -5.0 if last.endswith('er') else -1.5
    if token == ' wie':
        return -3.0 if 'so' in words[-4:] else -1.5
    if token in {' чем', ' как'}:
        return -3.0 if token == ' чем' else -0.9
    if last in {'that', 'those'}:
        return -1.0
    if DIMENSIONS.intersection(wordnet.base_forms(last, 'noun')):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (text + token)[-250:]), estimate(token, text)

programs.haiku:
"""Comparison closers: the word that ends a comparison and introduces its standard. Examples:
the "as" of "as big as" or "not as good as", the "than" of "bigger than", the "que" of
"más ... que", the "als" of "größer als", the "чем" of a Russian comparative, and the
"dan"/"niż" of Dutch and Polish. The component writes a negative value there: strongest
for "as ADJ as" equatives (with "not" strongest of all), "the same X as", and "than" after a
comparative adjective; it is near zero everywhere else. A weaker case is "such X as" (but
not "such as"), and "of" after a measure noun ("the size of", "that of").

The program is a set of word rules. It looks back a few words, within the same document, to
tell the comparison closer from its other uses: "as well as" and "as soon as" are idioms
that stay near zero, and "more than" / "greater than" are quantities rather than standards.
"""

READS = ()

# Comparison closers in other languages, with a typical size
OTHER_CLOSERS = {"als": -3.0, "чем": -3.5, "wie": -1.5, "como": -0.5, "как": -0.9,
                 "qu": -0.5, "che": -0.5, "dan": -3.0, "niż": -5.0}
# "as well as", "as soon as", "as far as" and "as long as" are idioms, weakly negative
IDIOM_MIDDLES = {"well", "soon", "far", "long"}
# "than" after these is a quantity ("more than 5"), not a standard of comparison
QUANTITY_BEFORE_THAN = {"more", "less", "greater", "fewer", "rather", "other", "different"}
# Spanish/French "que" is a comparison in most cases; "para que", "así que" are not
NOT_COMPARATIVE_BEFORE_QUE = {"para", "Así", "así", "ya"}
# nouns of measure: "the size of", "the speed of", and "that of", as a comparison of degree
MEASURE_NOUNS = {"size", "sizes", "mass", "price", "complexity", "speed", "height",
                 "weight", "magnitude", "depth", "breadth", "length", "width", "volume",
                 "distance", "richness", "scope", "that", "those"}


def _back(prefix, k):
    """The word k places before the newest token, stripped of spaces; '' outside its document."""
    p = len(prefix.token_strings) - 1
    if p - k < 0 or prefix.document_ids[p - k] != prefix.document_ids[p]:
        return ""
    return prefix.token_strings[p - k].strip()


def _as_value(prefix):
    """An English " as" (with its space), judged by the words before it."""
    b = [_back(prefix, k) for k in range(7)]
    if b[2] == "as" and prefix.token_strings[-3] == " as":   # "as ADJ as", "not as ADJ as"
        if b[1] in IDIOM_MIDDLES or b[1] == ",":
            return -1.0
        return -12.0 if "not" in b[3:5] else -7.0
    if b[3] == "as" or b[4] == "as":                          # "as many X as"
        return -4.0
    if b[1] == "same":                                        # "the same as"
        return -1.5
    if "same" in b[2:6]:                                      # "the same X as"
        return -5.0
    if b[1] != "such" and "such" in b[2:6]:                   # "such X as" (not "such as")
        return -2.5
    return 0.0


def _value(prefix):
    t = prefix.token_strings[-1]
    prev = _back(prefix, 1)
    if t == " as":
        return _as_value(prefix)
    if t.strip() == "than" or (t.strip() == "then" and prev.endswith("er")):
        return -0.5 if prev in QUANTITY_BEFORE_THAN else -3.0
    if t == " que":
        return 0.0 if prev in NOT_COMPARATIVE_BEFORE_QUE else -1.0
    if t == " of":
        return -1.0 if prev in MEASURE_NOUNS else 0.0
    return OTHER_CLOSERS.get(t.strip(), 0.0)


def step(carry, prefix, upstream):
    return None, float(_value(prefix))

programs.sol:
"""A negative response to likely decimal points.

Use the integer before a period and simple formatting cues: list numbering and
second points in dotted numbers weaken the response; currency, versions, Han
text, and recent decimals strengthen it. Other positions are near zero, apart
from a coarse document-start transient. Only the last 100 characters are kept.
"""
import regex as re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        if token.isdigit():
            value = -0.15
        elif token[0].isspace():
            value = -0.22
        else:
            value = -0.55
        return (doc, token[-100:]), value

    text = carry[1]
    value = 0.0
    if token == '.':
        match = re.search(r'([0-9]+)$', text)
        if match:
            number = match[1]
            before = text[:-len(number)]
            char = before[-1:] or ' '
            value = -0.49 + 0.05 * min(len(number) - 1, 2)
            if len(number) == 4:  # often a year, not a decimal
                value = -0.13
            elif len(number) > 4:
                value = -0.32
            if number == '0':
                value -= 0.32
            if re.search(r'(?:^|\n|\\n|\.\s)[ \t>*-]*$', before):
                value += 0.48
            if unicodedata.category(char) == 'Sc':
                value -= 0.47
            if char == '(':
                value -= 0.23
            if re.search(r'(?:_|\bv|version\s*|[a-zA-Z]-)$', before, re.I):
                value -= 0.29
            if re.search(r'\p{Script=Han}', before[-15:]):
                value -= 0.32
            decimals = len(re.findall(r'[0-9]\.[0-9]', before))
            value -= 0.12 * min(decimals, 3)
            if re.search(r'[0-9]\.$', before):
                value = 0.0
            value = min(0.0, value)
        else:
            value = -0.006
    return (doc, (text + token)[-100:]), value

"""Short Latin spelling continuations around h/H.

Negative responses mark h next to y or unusual h-cluster consonants.
They are strongest in short subword fragments, not whole long words.
The io/ion family of endings has the opposite sign. A short hy fragment
can leave a weaker response on its next continuation. This is a local
spelling approximation, not a semantic or grammatical classifier.
"""
READS = ()


def continuation(s):
    """Response to a token continuing an h-ending piece."""
    if not s or not s.isascii() or not s.isalpha():
        return 0.0
    n = len(s)
    if s.startswith('ion') and n <= 5:
        return 4.6 if n <= 4 else 1.7
    if s.startswith('io') and n <= 3:
        return 2.5
    if s[0] == 'y':
        if n <= 2:
            return -4.2
        return -2.4 if n == 3 else -0.5 if n == 4 else 0.0
    if n <= 3 and s[:2] in ('ay', 'ey', 'oy', 'uy'):
        return -2.2
    if s[0] in 'jvq':
        if n <= 2:
            return -4.1 if n == 1 else -0.8
        return -0.3 if n <= 4 else 0.0
    if s[0] in 'gfwx':
        if n <= 2:
            return -2.2 if n == 1 else -0.9
