"""Recognize familiar word starts stranded across a subword boundary.

A continuation such as 'thep' + 'ath' can finish 'path' even though the
whole identifier is unfamiliar. English word and word-prefix frequencies
measure that contrast. Ordinary recognizable words get little response.
Chat user labels and a document-initial Title: header are separate cases.
"""
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()

# The most frequent English word beginning with each spelling prefix.
PREFIX_FREQUENCY = {}
for word in top_n_list('en', 100000):
    if word.isascii() and word.isalpha():
        frequency = zipf_frequency(word, 'en')
        for length in range(1, min(20, len(word)) + 1):
            spelling = word[:length]
            PREFIX_FREQUENCY[spelling] = max(
                frequency, PREFIX_FREQUENCY.get(spelling, 0.0))


@lru_cache(maxsize=65536)
def frequency(word):
    return zipf_frequency(word, 'en')


def prefix_frequency(word):
    return PREFIX_FREQUENCY.get(word.lower(), 0.0)


def continuation_value(word, piece):
    restored = max(frequency(word[-n:] + piece)
                   for n in range(1, min(4, len(word)) + 1))
    whole = frequency(word + piece)
    one_letter = word[-1] + piece
    gain = frequency(one_letter) - frequency(piece)
    if restored - whole <= 4.25:
        if prefix_frequency(one_letter) <= 3.71:
            return 0.010 if restored - whole <= 2.32 else -0.034
        return -0.176 if gain >= -0.11 else -0.056
    if gain <= 2.71:
        return -0.563 if prefix_frequency(piece) <= 5.07 else -0.213
    return -2.211 if prefix_frequency(word) <= 3.92 else -1.051


