    start = re.match(r'[A-Za-z]+', text)
    if word and start:
        value = continuation_value(word, start.group())
    if previous == '<|im_start|>' and text == 'user':
        value = -0.600 if position == 1 else -1.159
    if position == 0 and text == 'Title':
        value = 0.248
    if position == 1 and previous == 'Title' and text == ':':
        value = -10.374
