"""Activation of layers.1.mlp.down_proj:870, predicted from a few readable rules.

1. A document that opens with "Title:" gets a very large value on the colon (10.66).
2. Commas after a word that introduces a clause are positive: strongly after "which,"
   "who,", "and,", "because,", "when,", "if,"; moderately after "but,", "or,", "that,";
   weakly after "so,", "then,". Commas after a transitional adverb that opens a sentence
   ("However,", "Moreover,", "For example,") are slightly negative.
3. Document-opening tokens: code and comment openers ("#", "//", "package", "import") are
   negative, and a leading newline, tab or indent is positive.
Everything else is predicted as 0.
"""
READS = ()
STRONG = {"and", "which", "who", "whom", "whose", "when", "because", "if", "where", "why",
          "since"}
MEDIUM = {"but", "or", "that", "what", "qui", "que"}
WEAK = {"so", "then", "as", "while", "though", "yet", "now", "perhaps"}
TRANSITIONS = {"however", "moreover", "furthermore", "additionally", "actually", "finally",
               "overall", "unfortunately", "interestingly", "nevertheless", "example",
               "instance", "addition", "indeed", "accordingly", "generally", "importantly"}
CODE_OPENERS = {"#", "//", "/*", "--", '"""', "__", "*", "package", "import", "from", "int"}
INDENT_OPENERS = {"\n", "\t", "  ", "   ", "\n\n"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    n = len(prefix)
    doc = prefix.document_ids
    if n == 1 or doc[-1] != doc[-2]:  # first token of a document
        if cur in CODE_OPENERS:
            return None, -0.6
        if cur in INDENT_OPENERS:
            return None, 0.4
        return None, 0.0
    if n == 2 or doc[-2] != doc[-3]:  # second token of a document
        if cur == ":" and s[-2].strip() == "Title":
            return None, 10.66
        return None, 0.0
    if cur == ",":
        prev = s[-2].strip().lower()
        if prev in STRONG:
            return None, 0.9
        if prev in MEDIUM:
            return None, 0.5
        if prev in WEAK:
            return None, 0.2
        if prev in TRANSITIONS:
            return None, -0.1
    return None, 0.0

