"""A spelling approximation: short pe/pi fragments and their continuations.

The main negative responses are to short pe fragments (especially pes/pest)
and the pick/piece stems.  An e-fragment supplied after p across a token break
is stronger, particularly in Greek and Cyrillic.  Completing a pe fragment
across another break also gives a negative response.  Per and most long fragments
are weak.  Han and Hangul are not romanized.  Paired middle dots
have a separate positive response.  A final 0.75 scale moderates the
responses.  This explains only part of the activity.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    if any('CJK' in unicodedata.name(c, '') or
           'HANGUL' in unicodedata.name(c, '') for c in text):
        return text.lower()
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    token = text.strip()
    continuing = text[:1].isalpha() and not text[:1].isspace()
    value = 0.001

    if token.startswith(('pe', 'pi')):
        tail = token[2:]
        if tail.startswith('r'):
            value = -0.09
        elif token.startswith(('pick', 'piec')):
            value = -1.6
        elif token.startswith('pe') and len(tail) <= 2 and tail.startswith('s'):
            value = -4.0
        elif token.startswith('pe') and len(tail) <= 1:
            value = -1.8
        else:
            value = -0.17
    elif raw == '··':
        value = 1.017
    elif continuing and previous.endswith('p'):
        if token.startswith('er'):
            value = -0.16
        elif token.startswith('e'):
            greek_or_cyrillic = any('GREEK' in unicodedata.name(c, '') or
                                   'CYRILLIC' in unicodedata.name(c, '') for c in raw)
            if greek_or_cyrillic and len(token) <= 4:
                value = -5.0
            elif len(token) <= 2:
                value = -3.2
            else:
                value = -1.4 if len(token) <= 4 else -0.4
        else:
            value = -0.1
    elif continuing and (previous.endswith('pe') or
                         (previous == 'e' and before.endswith('p'))):
        value = -4.0 if len(token) == 1 else (-1.5 if len(token) <= 3 else -0.22)
    elif continuing and 'pe' in previous:
        value = -0.6 if len(token) == 1 else -0.22
    return (doc, text, previous), float(0.75 * value)

"""A sparse, local spelling heuristic for this component.

Negative pulses mark short Cyrillic continuations (especially s-related
fragments), a+s spellings across scripts, and Chinese student/level terms.
