import regex
import cedict
import jmdict
from anyascii import anyascii

READS = ()
VOWELS = frozenset('аеёиоуыэюяіїє')
COMPOUND = {
    '内': 1.558, '內': 1.558,
    '外': 1.417, '上': 0.422,
    '下': 0.101, '中': -0.262,
    '大': -0.17, '小': -0.019,
}

@lru_cache(maxsize=8192)
def is_word(text):
    return bool(cedict.glosses(text) or jmdict.glosses(text))

@lru_cache(maxsize=32768)
def local_value(previous, token):
    if previous is None:
        return 0.0
    p, s = previous.strip(), token
    value = 0.0
    if len(s) >= 2 and set(s) == set('·'):
        value += -0.824

    if regex.fullmatch(r'\p{Script=Han}+', s):
        last = p[-1:]
