            value += COMPOUND[last]
        if last in ('中', '大', '小'):
            if s in ('一', '二', '三', '四'):
                value += -2.925
            if s in ('学生', '學生', '学校', '學校'):
                value += -2.471
        if s in ('大学生', '大學生'):
            value += -2.124

