    if len(b) == 2 and b[0] in VOWELS and b[1] == 'с':
        value += -0.244
        if a == 'д' and b[0] == 'и':
            value += -2.526
        elif a == 'л' and b[0] != 'о':
            value += -1.588
        elif a == 'р' and b[0] in 'еу':
            value += -1.04
        elif a == 'с':
            value += -2.119
    if a == 'с':
        if len(b) == 2 and b[0] in VOWELS:
            if b[1] in 'нм':
