                          else -0.734)
            if b[1] in 'дтпкбг':
                value += -0.875
            if b[1] in 'хфвжшз':
                value += (-0.772 if b[1] == 'х'
                          else -0.495)
        elif b == 'н':
            value += -1.569
        elif len(b) == 1 and b in VOWELS and b != 'е':
            value += -0.891
