"""layers.1.mlp.down_proj:875 - a few word-piece rules.

The component is a diffuse, lexical signal: its sign and size depend on which
specific word pieces are present, and no broad class (script, word-piece
position, token length) predicts it. Only a few small sets of pieces carry a
consistent sign, so this program predicts those and zero elsewhere:

1. Short Cyrillic syllables that split a Russian word mid-word ("с|ед|ация",
   "д|ис|курсы", "с|ин|тез"): negative.
2. Words for young people and students (学生, 大学生, 小学生, 老年人, ...):
   negative, strongest for 大学生.
3. A Chinese character that follows 内 / 外 / 上 inside one word (内定, 外观,
   上衣): positive.

Values are the mean activations of these pieces on training text. Together
they explain about 2% of the variance on held-out training rows.
"""

READS = ()

SYLLABLE_PIECES = {"ис", "ас", "ес", "ед", "ин", "сс", "ус", "их", "ар", "ай", "с"}
PEOPLE_PIECES = {"学生", "大学生", "小学生", "中学生", "老年人", "年轻人", "青少年", "大人", "平民", "大众"}
INSIDE_OUTSIDE_UP = {"内", "外", "上", "內"}


def _is_cjk(text):
    return len(text) > 0 and "一" <= text[0] <= "鿿"


def _is_mid_word(text):
    return len(text) > 0 and not text.startswith(" ") and text[0] not in "\n\r"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if _is_mid_word(token) and token in SYLLABLE_PIECES:
        return carry, -0.35
    if token in PEOPLE_PIECES:
        return carry, -0.75
    if same_doc and _is_cjk(token) and _is_mid_word(token):
        if prefix.token_strings[-2] in INSIDE_OUTSIDE_UP:
            return carry, 0.48
    return carry, 0.0

