            # A filename or object.member is not a lowercase namespace.
            if match.start() == 0 or tail[match.start() - 1] != '.':
                value = 2.1 if RUST_IMPORT.search(tail) else 1.5
    elif token == ':' and XML_PREFIX.search(tail):
        value = 1.35
    elif (token == '2' and tail and tail[-1].isascii()
          and tail[-1].isalpha()):
        value = 0.2
    elif token in {'.go', '.rs'}:
        value = 0.65
    elif token == '.mod' and previous.strip() == 'go':
        value = 0.72
    elif token in SOURCE_SUFFIXES:
        value = 0.26
    elif token == '.js':
        value = 0.12
    elif '`' in token:
        dense = sum(ticks) >= 8
        nbsp_code = '\xa0' in tail and '``' in tail
