            if token == '`':
                value = 1.35 if nbsp_code else 1.0
            elif token == ' `':
                value = 1.1 if nbsp_code else 0.7
            elif token == ' ``':
                value = 0.55
            elif token.endswith('`') and token.count('`') == 1:
