        remainder = token.rsplit('\n', 1)[-1]
        blank_line = not remainder or remainder.isspace()
    else:
        blank_line = blank_line and token.isspace()
    ticks = (ticks + ('`' in token,))[-32:]
    state = (document, token, blank_line, (tail + token)[-300:], ticks)
    return state, value

"""A spelling-sensitive detector of 'way' and related adverbs.

The response to 'way' is weak after definite/possessive determiners, strong
in 'no way' and existential 'there ... a way'.
Plurals, compounds, case and split spellings have separate amplitudes.
A small lexicon covers related adverbs and route words. Everything else is
zero; this does not model all the component's incidental lexical responses.
"""

READS = ()

RELATED_ADVERBS = {
    'anyway': 5.6,
    'anyways': 5.6,
    'somehow': 3.6,
    'somewhere': 2.7,
    'anywhere': 2.0,
    'elsewhere': 1.3,
    'everywhere': 1.3,
    'nowhere': 1.3,
    'away': 1.1,
    'everyday': 2.6,
    'anytime': 2.6,
    'sometime': 2.6,
    'differently': 0.9,
    'halfway': 7.3,
    'midway': 7.3,
}
DEFINITE = {
    'the', 'this', 'that', 'same', 'my', 'your', 'his', 'her',
    'our', 'their', 'its', "'s",
}
ROUTE_WORDS = {'highway', 'subway', 'runway', 'broadway'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()
    before = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            before = prefix.token_strings[-2].strip()
    previous = before.lower()
    joined = bool(token) and not token[0].isspace()
    value = RELATED_ADVERBS.get(word, 0.0)

    if word == 'way':
        value = 2.6
        if previous in DEFINITE or previous == 'by':
            value = 0.8
        elif previous in {'a', 'an', 'some', 'one'}:
            value = 3.8
            # Existential questions/statements: "is there a way?"
            for j in range(max(0, len(prefix.token_ids) - 5),
                           len(prefix.token_ids) - 2):
                if prefix.document_ids[j] == prefix.document_ids[-1]:
                    if 'there' in prefix.token_strings[j].lower():
                        value = 6.7
        elif previous == 'no':
            value = 6.8
        elif previous == 'any':
            value = 4.8
        elif previous == 'every':
            value = 6.5
        if joined:
            value = 7.8 if previous.endswith(('half', 'mid')) else 4.9
        if text[:1].isupper():
            value = 3.0 if not text.isupper() else 4.0
    elif word == 'ways':
        value = 6.7 if previous == 'of' else 4.5
        if previous == 'many':
            value = 5.1
        if joined:
            value = 3.0
        if text.isupper():
            value = 7.5
    elif word == '-way':
        value = 6.0
    elif word == 'sway':
        value = 4.3
    elif word in ROUTE_WORDS:
        value = 2.2
    elif word in {'weg', 'wege'}:  # German "way/ways"
        value = 2.3
    elif word == 'away' and joined:
        value = 2.5
    elif word in {'time', 'times'}:
        value = 2.3 if previous == 'every' else 0.0
    elif word in {'eway', 'eways'}:
        value = 4.7

    # Spellings across token boundaries: w|ay, W|ey, w|eg / we|ge,
    # and Japanese ウェ|イ (the English sound "way").
    if joined and previous.endswith('w'):
        if word == 'ay':
            value = 10.0 if before.endswith('W') else 6.8
        elif word == 'ays':
            value = 11.0
        elif word == 'ey':
            value = 6.9
        elif word.startswith('eg'):
            value = 4.8
    elif joined and previous.endswith('we') and word == 'ge':
        value = 4.0
    if word == 'イ' and before.endswith('ウェ'):
        value = 9.0
    return carry, value

programs.haiku:
"""Layer-1 MLP unit 877: the English word "way" (and its relatives).

What it responds to: the token "way" itself, read as a word meaning a method, means or
possibility. It fires hard after "no", "any", "a", "one", "some", "great" ("no way",
"any way", "a way to", "one way") and on "ways" and "anyway", "halfway", "midway",
"-way". It stays weak after "the", "this", "that", "same", "their", "its", "by", i.e.
"the way" in the sense of a path or of "this manner" ("along the way", "in this way").
Weaker, related hits: "away", "highway" and the adverbs somehow, somewhere, anywhere,
everyday, and "every time". Words that merely contain "way" (always, pathway, railway,
gateway, Norway) stay near zero, and so does almost everything else.

The program is stateless apart from the current word and the previous word, which it
tracks through the token strings, so it needs no model.
"""

READS = ()

# Words that point at a path or a fixed manner: "the way", "this way", "by the way".
PATH_WORDS = {"the", "this", "that", "these", "those", "same", "their", "its", "her",
              "his", "our", "my", "your", "by", "which", "whose", "'s"}
# Words before "way" that make it a method or a possibility: "no way", "a way to".
METHOD_WORDS = {"no": 6.5, "a": 4.2, "any": 4.7, "one": 4.9, "some": 4.2, "great": 4.4,
                "better": 3.8, "many": 4.5, "several": 4.5, "two": 4.5, "both": 4.5}
# Tokens that end in "way" but do not use it as a word.
NOT_WAY = {"always", "pathway", "pathways", "gateway", "railway", "hallway", "roadway",
           "speedway", "freeway", "driveway", "getaway", "parkway", "norway", "subway"}
# Related manner and place adverbs, with their typical strength.
ADVERBS = {"somehow": 3.5, "somewhere": 2.7, "anywhere": 2.5, "everywhere": 1.3,
           "elsewhere": 1.5, "everyday": 2.5, "differently": 1.0, "otherwise": 0.7}


def step(carry, prefix, upstream):
    new_doc = prefix.position > 0 and prefix.document_ids[-1] != prefix.document_ids[-2]
    word, prev_word = ("", "") if carry is None or new_doc else carry
    s = prefix.token_strings[-1]
    tok = s.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if prefix.position > 0 else ""
    # The letters of the current word so far, to catch words split over tokens ("Gallow|ay").
    if s.isalpha() and not s.startswith(" "):
        word = word + s.lower()
    elif s.strip().isalpha():
        prev_word, word = word, s.strip().lower()
    else:
        prev_word, word = "", ""

    value = 0.0
    if tok == "way":
        if prev in PATH_WORDS:
            value = 0.8
        else:
            value = METHOD_WORDS.get(prev, 2.5)
    elif tok == "ways":
        value = 4.5
    elif tok in ("anyway", "halfway", "midway", "eway", "-way"):
        value = 6.0
    elif tok == "away":
        value = 1.1
    elif tok.endswith("way") and tok not in NOT_WAY:
        value = 2.0
    elif tok in ADVERBS:
        value = ADVERBS[tok]
    elif tok == "time" and prev in ("every", "any"):
        value = 2.3
    elif s.isalpha() and not s.startswith(" ") and word.endswith("way"):
        value = 4.0
    return (word, prev_word), value

programs.sol:
"""Detect document headers and the boundaries of short, scraped excerpts.

The colon in an initial `Title:` header is strongly positive. A roughly
200-character, unfinished plain-text paragraph is treated as an excerpt:
its following Markdown ### heading is negative. Its blank line is also
negative when it follows another ### heading. `More information` carries
this response across the intervening navigation label. Paired middle dots
have a separate small negative response. Initial programming type/test words
and English question openers get positive estimates; an early lowercase
`title:` field gets a negative one. These are coarse templates for observed
peaks, leaving small token-specific activations unexplained.
"""
READS = ()

# Lexical families with elevated activations when they begin a document.
TYPE_WORDS = frozenset({
    'int', 'char', 'short', 'long', 'float',
    'double', 'bool', 'void', 'string',
})
QUESTION_AUXILIARIES = frozenset(
    'Do Does Did Is Are Am Was Were Can Could Will Would Shall Should '
    'Have Has Had Must May Might'.split()
)
QUESTION_WORDS = frozenset('What Which Why Where Who Whose When How'.split())


def is_excerpt(text):
    text = text.strip()
    return (200 <= len(text) <= 214
            and not any(c in text for c in '\n$\\`#')
            and text[-1:] not in '.!?:;"')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, paragraph, last, boundary = 0, '', '', '', 0.0
    else:
        _, position, previous, paragraph, last, boundary = carry
        position += 1

    value = -0.72 if token == '··' else 0.0
    if position == 0:
        if token == 'Title':
            value = 0.411
        elif token in TYPE_WORDS:
            value = 2.9
        elif token in {'test', 'tests'}:
            value = 2.0
        elif token in QUESTION_AUXILIARIES:
            value = 0.84
        elif token in QUESTION_WORDS:
            value = 0.54
    elif position == 1 and previous == 'Title' and token == ':':
        value = 6.81
    elif position == 2 and previous == 'title' and token == ':':
        value = -0.765
    elif token == '###' and not paragraph.strip():
        value = -boundary
    elif (paragraph + token).strip() == 'More information' and boundary:
        value = -1.15

    paragraph += token
    if '\n\n' in paragraph:
        finished, paragraph = paragraph.rsplit('\n\n', 1)
        if finished.strip() == 'More information' and boundary:
            value, boundary = -1.15, 1.15
        elif is_excerpt(finished):
            boundary = 0.95
            if last.lstrip().startswith('###'):
                value = -0.55
        else:
            boundary = 0.0
        last = finished
    # Long paragraphs cannot be short excerpts; bound the carried text.
    paragraph = paragraph[-600:]
    return (doc, position, token, paragraph, last, boundary), value

"""A leading-zero detector with a few smaller numerical responses.

Zero is strong at the start of a number, after letters, and in zero padding;
it is weak after nonzero digits. Decimal separators and byte escapes change
that distinction. Smaller rules cover subscript zero, five, written zero
values and underscores. A document-opening 'Title:' colon is a separate spike.
Most other tokens receive zero, with a small document-start correction.
"""
import re

READS = ()


def zero_value(before):
    digits = re.search(r'[0-9]*$', before)[0]
    number = re.search(r'[0-9.,]*$', before)[0]
    identifier = re.search(r'[a-zA-Z0-9]*$', before)[0]
    decimal_zeroes = bool(re.search(r'0\.0*$', before))
    last = before[-1:]
    if re.search('[1-9]', number):
        if re.search('[1-9]', identifier):
            # Long zero padding can overcome a preceding nonzero digit.
            tail = len(re.search(r'0*$', digits)[0])
            return 0.65 if tail >= 4 else -0.02
        if decimal_zeroes:
            return 0.9
        return 0.5 if not digits else 0.1
    if digits:
        return 3.0 if len(digits) >= 3 else 1.95
    if last.isalpha():
        if re.search(r'\\[a-z][a-z]$', before):
            return 0.2
        if re.search(r'\\x$', before):
            return 1.2
        return 1.2 if re.search('[1-9]', identifier) else 2.1
    if decimal_zeroes:
        return 1.6
    if last in '-_':
        return 1.05
    return 0.46 if last in '[({' else 0.67


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, raw = 0, b''
    else:
        _, position, raw = carry
    before = raw.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    state = (doc, position + 1, (raw + prefix.token_bytes[-1])[-256:])
    value = -0.11 if position == 0 else 0.0
    if token == ':' and position == 1 and before == 'Title':
        value = 15.84
    elif token == '0':
        value = -0.288 if position == 0 else zero_value(before)
    elif token == '₀':
        value = 1.38
    elif token == '5':
        value = -0.45 if position == 0 else 0.09
    elif len(token) == 1 and token in '12346789':
        value = -0.2 if position == 0 else -0.02
    elif token.strip().lower() in {'zero', 'false', 'null', 'none', 'five'}:
        value = 0.18
    elif token.strip().lower() == 'fifth':
        value = 0.29
    elif token.strip() == '_':
        value = 0.1
    return state, value

"""Approximate a spelling-sensitive response around the letter h.

Short hur/hort fragments are negative; hull and some other h fragments are
positive. A fragment may be one token or completed across a token boundary.
Intact words such as 'hold' and 'hundred' are not treated as 'hol' and 'hund'.
For hour(s), nearby quantities weaken the negative response, while definite
or possessive determiners strengthen it. There is a small negative tail into
another piece after hur, and an independent response to repeated middle dots.
Unmatched tokens get zero; this does not capture all of the component's activity.
"""
import re
from functools import lru_cache
from collections.abc import Mapping
import inflect

READS = ()
_engine = inflect.engine()
NUMBER_WORDS = {_engine.number_to_words(n) for n in range(101)}
NUMBER_WORDS |= {'hundred', 'thousand', 'million'}
QUANTIFIERS = {'few', 'several', 'many', 'couple', 'per'}
DETERMINERS = {'the', 'this', 'that', 'each', 'every', 'my', 'your',
               'her', 'his', 'our', 'their'}

# Exact short spellings, rather than arbitrary token identities.
SPELLINGS = (
    ('hour', r'hour(?:ly)?'), ('hours', r'hours'),
    ('hurt', r'hurt'), ('hurting', r'hurts|hurting'),
    ('hurry', r'hurry|hurried'), ('hur', r'h(?:ur[ld]?|uur|ür|eur)'),
    ('hull', r'hull'), ('hush', r'hush(?:ed)?'),
    ('hort', r'hort(?:on)?'), ('hol', r'holl?'), ('hof', r'hoff?'),
    ('hund', r'h(?:und|ond|ound)'), ('hove', r'hove'),
    ('hobic', r'hobic'), ('hq', r'hq'),
)
# At a split, the next piece may extend the fragment further.
SPLIT_PREFIXES = (
    ('hur', r'h(?:ur|uur|ür|eur)'), ('hour', r'hour'),
    ('hull', r'hull'), ('hush', r'hush'), ('hort', r'hort'),
    ('hol', r'hol'), ('hove', r'h(?:of|ov|ob)'),
    ('hund', r'h(?:und|ond|ound)'), ('hu_other', r'h(?:ui|uz|uff)'),
    ('h_vowel_r', r'h[aeiouö]*r'), ('h_lateral', r'h(?:ul|oo)'),
)
WEIGHTS = {
    'hur': -3.9, 'hurt': -8.0, 'hurting': -4.1, 'hurry': -5.5,
    'hort': -4.3, 'hush': -3.8, 'hull': 3.7, 'hund': 2.2,
    'hq': 1.8, 'hobic': 1.5, 'hof': 0.65, 'hol': 0.35,
    'hove': 0.35, 'hu_other': -1.3, 'h_vowel_r': -0.2,
    'h_lateral': 0.55,
    'h_digit_4': -3.4, 'h_digit_3': -1.8,
    'h_digit_2': -0.35, 'h_digit_other': -0.25,
    'hour': -3.0, 'hour_quantified': -1.2, 'hour_half': -4.6,
    'hour_definite': -4.1, 'hours': -1.2,
    'hours_quantified': -0.18, 'hours_half': -1.5,
    'hours_definite': -2.9,
}


@lru_cache(maxsize=8192)
def spelling(s, split=False):
    s = s.lower()
    if s.startswith('th'):
        s = s[1:]
    if not s.startswith('h'):
        return None
    for name, pattern in SPELLINGS:
        if re.fullmatch(pattern, s):
            return name
    if split:
        for name, pattern in SPLIT_PREFIXES:
            if re.match(pattern, s):
                return name
        if s[1:2].isdigit():
            return 'h_digit_' + (s[1] if s[1] in '234' else 'other')
    return None


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', None)
    _, previous, context, previous_mode = carry
    token = prefix.token_strings[-1]
    mode = spelling(re.sub(r'^[\W_]+', '', token))
    continues_word = bool(token and token[0].isalnum())
    # Do not interpret the h in common ch/sh/wh/gh digraphs as a fresh h.
    if continues_word and not previous.lower().endswith(('ch', 'sh', 'wh', 'gh')):
        j = previous.lower().rfind('h')
        if j >= 0 and len(previous) - j <= 4:
            old = previous[j:]
            if old.isalpha():
                combined = spelling(old + token, True)
                if combined and combined != spelling(old, True):
                    mode = combined
    if mode in ('hour', 'hours'):
        words = re.findall(r'\w+', context.lower())[-3:]
        if any(w.isdigit() or w in NUMBER_WORDS or w in QUANTIFIERS for w in words):
            mode += '_quantified'
        elif 'half' in words:
            mode += '_half'
        elif any(w in DETERMINERS for w in words):
            mode += '_definite'
    value = WEIGHTS.get(mode, 0.0)
    if mode is None and continues_word and previous_mode == 'hur':
        value = -1.8
    if len(token) >= 2 and all(c == '·' for c in token):
        value = 1.48
    return (doc, token, (context + token)[-100:], mode), value

