"""Layer 1, MLP output unit 881: a lexical detector for "hour" and the "hurt" family.

Plain-terms summary of what it predicts (negative means the unit is pushed down):
- "hurt" and its relatives, spelled as a whole word or starting a word (hurt, hurts, hurting,
  hurry, hurried, hurl, Hur-, Hort-, Horton): strongly negative, about -5.
- "hour" as a time-of-day noun ("the hour", "this hour", "lunch hour"): about -6 after a
  determiner such as the/this/its, about -3 otherwise. After a number or "per" ("2 hour",
  "per hour") it is nearly silent, about -1.
- "hours": about -2 when it is a time span or opening hours, about 0 after a number ("5 hours").
- "rush" and its forms: about -1.5.
- "hull" and "HQ": positive, about +3.
- Every other token: 0. The unit's activation on other tokens is small noise, not modelled.

The program reads the letters of the word being written (so a word split over several tokens
is recognised as it is completed) and the token before it, and keeps no state between tokens.
"""

import re

READS = ()

HURT_START = ("hurt", "hurr", "hurl", "hort")
RUSH = ("rush", "rushed", "rushing", "rushes")
DETERMINERS = {"the", "this", "that", "its", "their", "his", "her", "my", "your", "our"}
AMOUNTS = {"per", "several", "few", "many", "couple", "some", "extra", "-",
           "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
           "eleven", "twelve", "twenty", "thirty", "forty", "fifty", "hundred"}


def current_word(strings):
    """Lowercase letters of the word being written, up to and including the newest token."""
    parts = []
    for text in reversed(strings[-8:]):
        letters = re.search(r"[A-Za-z]*$", text).group(0)
        parts.append(letters)
        if letters != text:
            break
    return "".join(reversed(parts)).lower()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = current_word(strings)
    before = strings[-2].strip().lower() if len(strings) > 1 else ""
    after_number = before in AMOUNTS or before.replace(".", "").replace(",", "").isdigit()

    if word == "hour" or word == "hourly":
        if after_number:
            return None, -1.0
        return None, (-6.0 if before in DETERMINERS else -3.0)
    if word == "hours":
        return None, (-0.1 if after_number else -2.0)
    if word == "hur" or word.startswith(HURT_START):
        return None, -5.0
    if word in RUSH:
        return None, -1.5
    if word in ("hull", "hq"):
        return None, 3.0
    return None, 0.0

