}

BEFORE_VOWEL = {
    'a': (-0.804, 0.228),
    'e': (-0.704, 0.156),
    'i': (-1.255, -0.188),
    'o': (-0.697, 0.294),
    'u': (-0.32, -0.024),
    'y': (-0.553, 0.155),
}


@lru_cache(maxsize=100000)
def word_evidence(word):
    return tuple(max(0.0, zipf_frequency(word, lang) - 2.0) ** 2
                 for lang in LANGUAGES)


def language_update(scores, word, token):
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if part.isalpha():
            word += part.lower()
        else:
            if word:
                evidence = word_evidence(word)
                scores = tuple(.86 * a + b for a, b in zip(scores, evidence))
            word = ''
    evidence = scores if any(scores) or not word else word_evidence(word)
    group = GROUP[max(range(len(evidence)), key=evidence.__getitem__)]
    return scores, word, group


@lru_cache(maxsize=100000)
def letters(token):
    text = unicodedata.normalize('NFD', token.lower())
    return ''.join(c for c in text if c.isalpha() and not unicodedata.combining(c))


def spelling(token, previous, group):
    text = letters(token)
    if not text:
        return 0.0
    scale = min(1.0, 4.0 / len(text))
    total = 0.0
    for char, family in (('з', 'cyr'), ('z', 'lat'), ('ж', 'zh'),
                         ('ز', 'arab'), ('ζ', 'greek')):
        if char not in text:
            continue
        j = text.rfind(char)
        distance = min(3, len(text) - j - 1)
        value = POSITION[family][distance]
        if family in ('cyr', 'lat'):
            col = int(family == 'lat')
            tags = []
            if token[0].isspace():
                tags.append('word_initial')
            if len(text) == 1:
                tags.append('single')
            before = text[j - 1] if j else ''
            if not j and token[0].isalpha() and previous[-1:].isalpha():
                before = letters(previous)[-1:]
                if before:
                    tags.append('medial')
            if before:
                tags.append('preceded_vowel' if before in 'aeiouyаеиоуыэюя'
                            else 'preceded_consonant')
                for vowel, equivalents in (('a', 'aа'), ('e', 'eеэ'), ('i', 'iи'),
                                           ('o', 'oо'), ('u', 'uую'), ('y', 'yы')):
                    if before in equivalents:
                        value += BEFORE_VOWEL[vowel][col]
            if j + 1 < len(text):
                after = text[j + 1]
                tags.append('following_a' if after in 'aа' else
                            'following_i' if after in 'ieие' else
                            'following_y' if after in 'yы' else 'following_other')
            if any(c in token.lower() for c in 'áéíóúý'):
                tags.append('acute_vowel')
            for char, tag in (('ź', 'acute_z'), ('ż', 'dot_z'), ('ž', 'caron_z')):
                if char in token.lower():
                    tags.append(tag)
            value += sum(MODIFIER[tag][col] for tag in tags)
        if family == 'lat':
            value *= AMPLITUDE[group]
        total += scale * value
    return total


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        scores, word, previous, first, second = (0.0,) * len(LANGUAGES), '', '', 0.0, 0.0
    else:
        _, scores, word, previous, first, second = carry
    scores, word, group = language_update(scores, word, token)
    current = spelling(token, previous, group)
    continuation = bool(token) and token[0].isalpha()
    size = max(1, sum(c.isalpha() for c in token)) ** .5
    tail = (0.8 * first + 0.2 * second) / size if continuation else 0.0
    extra = 0.0
    if token == '.com':
        extra = 1.117 * (1.0 if 'github' in previous.lower() else .18)
    if token == ' -' and previous.rstrip().endswith('@@'):
        extra = 1.152
    state = (doc, scores, word, token, current, first if continuation else 0.0)
    return state, float(current + tail + extra)

