"""Recognize word-initial 'at' and nearly completed UTF-8 characters.

The strongest English response is to 'at', except in verb-selected phrases
such as 'look at', 'aim at', or 'arrive at'. 'Attend' also responds.
The Python idiom 'with open' receives a smaller positive value.
A separate response occurs one byte before a multibyte character is complete;
its size depends on script, whitespace, and whether this token is a lone byte.
Everything else is approximated by zero. State resets at document boundaries.
"""
import codecs
import re
import unicodedata

READS = ()

DIRECTED_STEMS = (
    'look', 'aim', 'target', 'stare', 'staring', 'gaz', 'yell', 'laugh',
    'scoff', 'arriv', 'attempt',
)
NORDIC_FUNCTION_WORDS = set('og ikke det til som har på af med også'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        previous = ''
    else:
        _, decoder, previous = carry
    b = prefix.token_bytes[-1]
    text = decoder.decode(b, final=False)
    pending = decoder.getstate()[0]
    s = b.decode('utf-8', 'replace')
    word = s.lstrip(" \t\r\n—–-‘’“\"'(").strip()
    value = 0.0

    if word in ('at', 'At', 'AT'):
        attached = (s[0].isalpha() and previous and
                    (previous[-1].isalnum() or previous[-1] == '_'))
        if attached:
            value = -0.17 if word == 'at' else 0.0
        elif word == 'AT':
            letters = ''.join(c for c in previous[-60:] if c.isalpha())
            value = 1.13 if letters and letters.isupper() else 0.25
        else:
            value = 1.13
            if word == 'at':
                words = re.findall(r'[^\W\d_]+', previous.lower())
                last = words[-1] if words else ''
                if last in ('up', 'down', 'back', 'closer', 'directly'):
                    last = words[-2] if len(words) > 1 else ''
                if last.startswith(DIRECTED_STEMS) or last == 'shot':
                    value = -0.15
                elif not previous:
                    value = 0.31
                elif (not previous.rsplit('\n', 1)[-1].strip() and
                      re.search(r':\d+|Error|Traceback', previous)):
                    value = 0.4
                elif sum(w in NORDIC_FUNCTION_WORDS for w in words[-20:]) >= 2:
                    value = -0.2
    elif re.fullmatch(r'attend(?:ed|ing|s)?', word) and s[0].isspace():
        value = 0.86
    elif word == 'open' and re.search(r'\bwith\s*$', previous):
        value = 0.73

    # A representative completion estimates script, not the unseen next byte.
    if pending:
        lead = pending[0]
        width = 2 if lead < 224 else 3 if lead < 240 else 4
        if len(pending) == width - 1:
            if len(b) == 1 and 128 <= b[0] < 192:
                value = 1.43
            elif width >= 3:
                ch = (pending + b'\xa0').decode('utf-8', 'replace')
                name = unicodedata.name(ch[0], '')
                if 'HANGUL' in name:
                    value = 0.95 if b.startswith(b' ') else 0.6
                elif b.startswith(b' '):
                    value = 0.13
                elif 'CJK' in name:
                    value = 1.0
                elif lead == 224:  # Most South Asian writing systems.
                    value = 0.55
                else:
                    value = 0.85 if ch[0].isalpha() else 0.3
                if text.strip():  # A larger token, not just a character fragment.
                    value *= 0.4
            else:
                ch = (pending + b'\xa0').decode('utf-8', 'replace')[0]
                name = unicodedata.name(ch, '')
                if unicodedata.category(ch).startswith('M'):
                    value = 1.0
                elif any(script in name for script in
                         ('CYRILLIC', 'HEBREW', 'ARABIC')):
                    value = 0.6
                elif 'LATIN' in name and ord(ch) >= 256:
                    value = 0.6
                else:
                    value = 0.15
                if text.strip():
                    value *= 0.5
        elif width == 3 and lead >= 234 and lead <= 237:
            value = 0.6
        elif 228 <= lead <= 233 and not b.startswith(b' '):
            value = 0.95
        else:
            value = 0.07

    return (doc, decoder, (previous + text)[-160:]), float(value)

"""Approximate a local sibilant-fragment feature, not individual words.

Short sar/zar and sand fragments usually give negative values. Short
r/d/n continuations after s/z also do; awa and Greek epsilon can be positive. Case, token boundaries and common Romance/English suffixes
soften false matches. Only the current and previous token are inspected.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
# Rime after a preceding s, z, or x. Longer rimes are weaker matches.
RIMES = (
    (r"ar", (-6.9, -3.4, -0.3)),
    (r"ars", (-7.8, -3.5, 0.0)),
    (r"ar[aeiouy]", (-4.1, -2.7, 0.0)),
    (r"ar[dmnt]", (-3.4, -1.5, 0.0)),
    (r"ar[a-z]{2,3}", (-1.8, -1.1, 0.0)),
    (r"and[aeior]{0,2}", (-4.2, -1.3, -0.7)),
    (r"ad[a-z]{0,4}", (-0.9, -0.4, 0.0)),
    (r"ra?", (-1.9, -0.3, 0.0)),
    (r"ds?", (-1.0, 0.0, 0.0)),
)

@lru_cache(maxsize=8192)
def latin(text):
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    previous = ""
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    raw = prefix.token_strings[-1]
    if raw.lower() == "aar":
        raw = raw[1:]
    raw = raw.replace("ь", "").replace("Ь", "")
