    native = all(ord(c) < 128 or "LATIN" in unicodedata.name(c, "")
                 or "CYRILLIC" in unicodedata.name(c, "") for c in raw)
    match = re.fullmatch(r"([a-z]{0,3})([sz])ars?", q)
    if native and match:
        z = match[2] == "z"
        value += (-1.3, 1.0)[z] if match[1] else (-4.4, -1.1)[z]
        if raw.strip().isupper():
            value -= 1.4
        if previous[-1:].isalpha() and raw[:1].isalpha():
            value -= 2.4
    if native and q in ("sand", "sands"):
        value -= 3.1 if raw.strip().istitle() else 3.5
    if native and re.fullmatch("[sz]r", q):
        value -= 1.4

    # A new capitalized segment generally starts a word (including CamelCase).
    across = p.endswith(("s", "z", "x")) and s[:1].isalpha()
    across &= not (raw[:1].isupper() and not previous.strip().isupper())
    if across:
        source = "szx".index(p[-1])
        accented = any(c in raw.lower() for c in "áàâäãå")
        for pattern, scores in RIMES:
            if re.fullmatch(pattern, s):
                if not (accented and s.startswith("ar")):
                    strength = 0.4 if previous.endswith(("ц", "Ц")) else 1.0
                    value += scores[source] * (strength if s.startswith("ar") else 1)
                break
        if s.startswith("awa"):
            value += 2.3
        if raw == "ε":
            value += 1.6
        if raw == "α":
            value -= 1.2
        if raw.startswith(("а", "е", "э")) and len(raw) <= 3:
            value += 0.2
        if not (previous + raw).strip()[:1].isupper():
            word = p.strip() + s
            en = zipf_frequency(word, "en")
            romance = max(zipf_frequency(word, "es"), zipf_frequency(word, "pt"))
            if source == 0 and romance > en + 0.6:
                if s == "ar" and romance > 3.0:
                    value += 4.0  # Common infinitives, not unfamiliar sar names.
                if s == "ando":
                    value += 3.0  # Romance gerund ending.
            if s in ("ary", "ari", "ario", "arily") and en > 2.5:
                value += 2.3

    if p.endswith(("ps", "ts", "ls")) and re.fullmatch("ars?|ar[aeiouy]", s):
        value -= 3.7
    if p.endswith(("sa", "za")) and re.fullmatch("a?r[aeiou]?", s):
        value -= 2.7
    if p.strip() in ("sand", "sands") and s in ("ing", "y"):
        value -= 2.2
    if previous.endswith("<?") and raw == "php":
        value += 1.4  # PHP opening tag.
    return None, value

