from anyascii import anyascii
from functools import lru_cache
import codecs
import re
import regex
import cedict

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    s = anyascii(text).lower().replace('rwn', 'ron')
    electron = False
    if len(text.strip()) == 2 and text.strip().endswith('子'):
        electron = any(g.lower() in ('electron', 'electronic', 'electronics')
                       for g in cedict.glosses(text.strip()))
    japanese = bool(regex.search(r'[\p{Hiragana}\p{Katakana}]', text))
    return s, electron, japanese


