        before, after = s.rsplit('ron', 1)
        if 'lectron' in s:
            return 6.7 if after in ('', 's') else 1.6
        if not before and after in ('', 's', 'ic'):
            if not internal:
                return 2.7
            if tail.endswith('hed'):
                return 1.3
            if tail.endswith('neut'):
                return 5.7
            if tail.endswith('t'):
                return 9.3
            if after == 'ic':
                return 7.5
            if tail.endswith(('c', 'ch', 'k')):
