import unicodedata

READS = ()

# Programming declarations and imports, when they begin a document.
CODE_OPENERS = {
    'using': -21.9,   # C# / C++ namespace directive
    'class': -18.7,
    'string': -14.2,
    'module': -12.4,
    'int': -8.9,
    'def': -7.2,
    'type': -6.8,
    'from': -5.7,
    'import': -4.0,
    'package': -2.8,
    'const': -3.0,
    'var': -3.0,
    'function': -3.0,
}
PREPOSITIONS = set('of to in for on with as at from by about into over after '
                   'under between through before during without against'.split())
CONJUNCTIONS = set('and or but nor so yet although while because if when '
                   'that than'.split())


def onset(text):
    if text == '<|im_start|>':
        return 1.3
    if text == '<|endoftext|>':
        return -4.3
    if text and not text.strip(' '):
        return -4.6
    if text.isspace():
        return 1.9 if text == '\n' else -0.3
    if text in CODE_OPENERS:
        return CODE_OPENERS[text]
    word = text.strip()
    if word.isascii() and word.isdecimal():
        return -3.1 if word == '0' else -5.3
    if word == '.':
        return -10.9 if text == '.' else -2.3
    if word in {').', '].', '}.'}:
        return -10.0
    if word and not word.strip('-'):
        return -5.5 if '\n' not in text else 1.0
    if word and not word.strip('^'):
        return -2.2
    if word and not word.strip('#'):
        return -1.3 if len(word) == 1 else -3.5
    if text == '?':
        return -5.8
    if text == ',':
        return -2.0
    if text == '。':
        return -4.0
    if word == 'The':
        return -3.0 if text.startswith(' ') else -1.5
    if word.lower() in PREPOSITIONS:
        return -0.5 if text.startswith(' ') else -1.2
    if word.lower() in CONJUNCTIONS:
        return -0.2
    if len(word) == 1 and word.isupper() and not word.isascii():
        return -0.8 if text.startswith(' ') else -2.0
    # Isolated closing, other, or connector punctuation.
    if (len(text) == 1 and text.isascii() and
            unicodedata.category(text) in {'Pe', 'Po', 'Pc'}):
        return -1.2
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            if text.startswith(' '):
                return -0.8 if word.isupper() else 0.5
            return -2.0
        if text.startswith(' ') and word.islower():
            return 1.5
        return 1.0
    return 0.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = onset(prefix.token_strings[-1])
        return (doc, token, value), value
    if token == carry[1]:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

"""A local spelling contrast, strongest when a syllable is split across tokens.

After t/g, am-, av-, ast- and ust-like continuations have negative writes;
ang-, ach- and some stop-consonant continuations have positive writes.
Ordinary whole words and productive endings behave much more weakly, so
only a few short whole-stem patterns are included. Longer preceding
tokens weaken the split-spelling signal; all-capital ones strengthen it.
This is a spelling approximation, not a semantic or universal phonetic rule.
"""
import regex as re
from anyascii import anyascii

READS = ()


def spelling(previous, current):
    p = anyascii(previous).lower()
    # Transliteration is useful for Cyrillic and Arabic continuations, but
    # must not turn unrelated Han characters into matching Latin syllables.
    alphabetic = current.isascii() or re.search(
        r'[\p{Script=Cyrillic}\p{Script=Arabic}]', current
    )
    s = anyascii(current).lower() if alphabetic else ''
    split = not current[:1].isspace() and bool(re.search('[tg]$', p))
    if split and s:
        length = min(len(previous.strip()), 8)
        scale = 1 - 0.12 * length + 0.18 * previous.strip().isupper()
        if re.fullmatch(r'am(?:m|a|ma)?', s):
            return scale * -4.0
        if s.startswith('am'):
            return scale * -0.8
        if s.startswith('av'):
            return scale * -3.6
        if s.startswith(('ast', 'ats')):
            return scale * (-1.7 if len(s) <= 3 else -0.8)
        if re.match('a[bdfw]', s) and not s.startswith('abl'):
            return scale * -1.2
        if s.startswith('ust'):
            return scale * (-5.1 if s == 'ust' else -1.7)
        if re.fullmatch(r'us+s?', s):
            return scale * -1.1
        if s == 'ung':
            return scale * -0.55
        if s == 'ost':
            return scale * -1.2
        if re.match(r'a(?:ng|nk)', s):
            return scale * (3.9 if s in ('ang', 'angs') else 1.45)
        if s.startswith('ach'):
            return scale * (3.1 if s in ('ach', 'acha') else 0.85)
        if s.startswith(('ack', 'ak')):
            return scale * 0.5
        if s.startswith(('act', 'atic')):
            return scale * 0.85
        if re.fullmatch(r'[^a-z]*g', p) and re.match('a[gt]', s):
            return scale * 1.45
        if s in ('ough', 'uck'):
            return scale * 2.7

    # A complete short stem is not equivalent to a common whole-word token:
    # for example, gam is active whereas game is not.
    if current.isascii():
        stem = re.sub(r'^[^a-z]*', '', s)
        if re.fullmatch(r's?[tg]am', stem):
            return -2.8
        if re.match(r'[tg]ast', stem):
            return -1.2
        if stem == 'gust':
            return -2.65
        if re.fullmatch(r'gang(?:s|e|es)?', stem):
            return 2.0
        if re.fullmatch(r'tang(?:s|le|led)?', stem):
            return 0.75
    if re.search(r'[tg][ao]$', p) and s in ('ng', 'iga'):
        return 0.85

    # Parallel short spelling transitions in Greek and Thai.
    if previous.endswith(('τ', 'Τ')) and current.startswith(('η', 'ή', 'ὴ')):
        return 0.4
    if previous.endswith('ก') and current.startswith('ัง'):
        return 2.7
    if previous.endswith('ต'):
        if current.startswith('ัว'):
            return -1.2
        if current.startswith('่อ'):
            return 0.65
        if current.startswith('ิด'):
            return 3.0
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    current = prefix.token_strings[-1]
    value = spelling(previous, current)
    if tail.endswith('게이') and current.startswith('트'):
        value = 3.0
    return (doc, current, (tail + current)[-4:]), float(value)

"""Approximate the component's context-free opening-token response.

At a document opening (also an initial run of identical tokens), word shape,
spacing and English word frequency set the response. Capitals and short word
fragments tend to be positive; spaced common words tend to be negative. Once
there is varied preceding context, predict zero. Individual tokens have much
more variation than these broad classes capture.
"""
from wordfreq import zipf_frequency
import regex

READS = ()


def opening(s):
    t = s.strip()
    if s.startswith('<|') and s.endswith('|>'):
        return 0.19
    if not t:
        return -0.13
    if t.isdigit():
        return -0.21
    if t.isascii() and t.isalpha():
        f = zipf_frequency(t.lower(), 'en')
        if s[0].isspace():
            if t.istitle() and f < 4.5:
                return 1.64
            return -0.44 if f >= 4.5 else 0.0
        if t.isupper():
            return 2.44 if len(t) == 1 else 3.05
        if len(t) == 1:
            return 1.54
        if t.lower() in {'a', 'an', 'the'}:
            return 0.21
        if len(t) >= 7:
            return 0.1
        return 0.54 if f >= 5.5 else 1.61
    if regex.search(r'\p{Hangul}', t):
        return 2.34
    if regex.search(r'\p{Cyrillic}', t):
        return 0.65
    if regex.search(r'\p{Arabic}', t):
        return 1.2
    if regex.search(r'\p{Han}|\p{Hiragana}|\p{Katakana}', t):
        return 0.6
    if any(c in t for c in '\"\'()[]{}【】「」'):
        return 0.24
    if '_' in t:
        return 3.2
    if any(c.isalpha() for c in t):
        return 1.14
    if all(c in '=+-*/<>%&|^~!?' for c in t):
        return 1.09
    return -0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening(prefix.token_strings[-1])
        return (doc, token, value), value
    if carry[1] == token:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

programs.haiku:
"""First token of a document, scored by what kind of token it is.

Layer 1's MLP writes this component's contribution into the residual stream. Nearly all of
its activation sits on the first token of each document (the token right after
<|endoftext|>, or the first token of a row). There, attention sees only that token, so the
value is set by the token's own form. Elsewhere the component is almost silent, and this
program predicts 0 at every other position.

At a document start it predicts, roughly from the fitted class means:
- a word after a space (" the", " decision", " people"): negative, about -0.7;
- a short, uncommon word after a space: slightly positive, about +0.2;
- a code-like or symbol-joined piece with no space ("__", "//", "(use", "export"): +1.5;
- a capitalised piece with no space that is not a common word: +1.7 to +2.0, as in word
  fragments like "Contr", "Esc", "Desc" (very short ones highest);
- a capitalised common word ("The", "People"): about 0;
- a long capitalised piece: +0.5;
- a short lowercase word with no space: +1.2; a longer one: about 0;
- a lone punctuation mark or digit: slightly negative.
"""

READS = ()

# Common English words: function words and everyday words that start whole words.
COMMON = frozenset(
    "the a an of to and in is that for with on at by from as or it this be are was were "
    "have has had you not will can your our all more about their they we he she his her "
    "its one which who what when where how there these other than then also into just like "
    "only over such some time year people make good new first last work use may get been "
    "would could should do does did if so no up out".split()
)


def step(carry, prefix, upstream):
    # Only the first token of a document is scored; all other positions predict 0.
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return None, 0.0
    tok = prefix.token_strings[-1]
    core = tok.strip()
    if not core:
        return None, 0.0
    word = core.isalpha()
    common = core.lower() in COMMON
    if tok.startswith(" "):
        value = -0.7 if (common or len(core) >= 5) else 0.2
    elif not word and len(core) >= 2:
        value = 1.5
    elif core[0].isupper():
        if len(core) <= 2:
            value = 2.0
        elif common:
            value = 0.1
        elif len(core) <= 5:
            value = 1.7
        else:
            value = 0.5
    elif word and len(core) <= 6 and not common:
        value = 1.2
    elif word:
        value = 0.1
    else:
        value = -0.2
    return None, value

programs.sol:
"""Approximate a negative subject-matter cue, rather than all prepositions.

Recognize topical words, 'about', and complements such as 'related to',
'interested in', and 'deals with'. 'On' is strongest after writing or study
terms, weaker after ordinary action/dependence words. WordNet supplies
inflections and semantic classes. Numbers are fitted activation levels.
A 160-character trailing buffer is reset at each document boundary.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

@lru_cache(maxsize=30000)
def roots(word):
    return frozenset((word, *wordnet.base_forms(word)))

@lru_cache(maxsize=30000)
def kind(word, concept):
    return wordnet.is_a(word, concept)

ACTION_ON = set('base depend rely count put get hold go carry take turn move '
                'keep build draw press click run live bear release occur '
                'fall hang sit stand walk rest lie place appear display'.split())
RELATION = set('relate pertain regard respect reference relation relevant'.split())
STUDY = set('research study knowledge information understanding training '
            'education expertise expert degree qualification certification'.split())
TOPIC = set('topic theme subject matter issue question problem field area'.split())
INQUIRY = set('understanding study knowledge treatment examination investigation '
             'discussion analysis exploration handling overview description'.split())

# Preposition, the preceding word's meaning, predicted activation.
COMPLEMENTS = (
    ('to', RELATION, -1.23),
    ('to', {'dedicate', 'devote', 'attention'}, -1.16),
    ('of', TOPIC, -0.56),
    ('of', INQUIRY, -0.40),
    ('in', {'specialize'}, -3.0),
    ('in', {'interest', 'interested'}, -1.13),
    ('in', STUDY, -1.29),
    ('with', {'deal', 'concern', 'obsess', 'familiar', 'familiarize'}, -0.93),
    ('at', {'look', 'glance'}, -0.71),
    ('into', {'look', 'research', 'investigate', 'inquire'}, -1.91),
)
# Translations of topical 'about/on', with language-specific ambiguity.
OTHER_ABOUT = {
    'sobre': -2.98, 'sur': -1.08, 'über': -0.73,
    'о': -0.56, 'об': -0.30, 'về': -2.23,
}
PREPOSITIONS = {'on', 'in', 'of', 'to', 'at', 'with', 'into', 'around', 'about'}
BASELINES = {'into': -0.14, 'around': -0.31}


def predict(token, tail):
    s = token.strip().lower()
    boundary = not tail or token[:1].isspace() or not tail[-1:].isalpha()
    words = re.findall(r'[a-z]+', tail.lower())
    prev = words[-1] if words else ''
    # Preserve the topic noun through a copula: 'the focus is on ...'.
    if prev in {'is', 'are', 'was', 'were', 'be', 'been'} and len(words) > 1:
        prev = words[-2]
    p = roots(prev)
    if s in PREPOSITIONS:
        if not boundary:
            return 0.0
        if s == 'about':
            return -0.91
        if s == 'on':
            if p & ACTION_ON:
                return -0.08
            if len(prev) < 3 or prev in {'this', 'that', 'be', 'was', 'are', 'were'}:
                return -0.10
            if p & {'effect', 'impact', 'influence'}:
                return 0.0
            if kind(prev, 'literary composition') or kind(prev, 'publication'):
                return -1.98
            if kind(prev, 'educational activity'):
                return -2.5
            if kind(prev, 'recording'):
                return -0.74
            if p & STUDY:
                return -2.55
            if 'work' in p:
                return -0.89
            if kind(prev, 'statement') or kind(prev, 'discussion'):
                return -1.20
            if p & {'focus', 'concentrate', 'emphasis', 'attention', 'center'}:
                return -1.47
            classes = wordnet.categories(prev)
            if 'noun.communication' in classes:
                return -0.66
            if 'noun.cognition' in classes:
                return -0.47
            return -0.33
        for prep, meanings, value in COMPLEMENTS:
            if s == prep and p & meanings:
                return value
        if s == 'to' and re.search(r'when\s+it\s+(?:comes|came)\s*$', tail.lower()):
            return -2.96
        return BASELINES.get(s, 0.0)
    if s in {'regarding', 'concerning'}:
        return -1.26
    if boundary and s in OTHER_ABOUT:
        return OTHER_ABOUT[s]
    if s in {':', '：'}:
        return -0.09
    if s == '§':
        return -0.54
    if not boundary or not s.isalpha() or len(s) > 24:
        return 0.0
    r = roots(s)
    if r & {'topic', 'theme'}:
        return -0.90
    if r & {'subject', 'matter', 'issue', 'question', 'field', 'area'}:
        return -0.19
    if r & {'discuss', 'examine', 'explore', 'investigate', 'address'}:
        return -0.46
    if r & {'focus', 'concern', 'emphasis'}:
        return -0.61
    if 'cover' in r:
        return -0.56
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, tail)
    return (doc, (tail + token)[-160:]), float(value)

programs.haiku:
"""Aboutness: a negative response on the word that introduces the subject matter of a text, talk,
field or discussion: 'on' or 'about' after 'book', 'information', 'talk' or 'focused', and 'in',
'of' or 'to' after 'expertise', 'field', 'related' or 'regard'."""
READS = ()

ABOUT_PREPS = {" on", " about", " regarding", " concerning", " upon", " around", " over",
               " sur", " sobre", " über", " auf", " о", " об", " по"}
DOMAIN_PREPS = {" to", " in", " of"}
WORKS = {" book", " books", " paper", " papers", " article", " articles", " video", " videos",
         " literature", " thesis", " essay", " essays", " lesson", " conference", " course",
         " documentary", " podcast", " textbook", " post", " posts", " report", " research",
         " studies", " information", " discussion", " advice", " data", " content", " material",
         " series", " education", " training", " details", " knowledge", " worksheets", " section",
         " committee", " Committee", " lectures", " exhibit", " blog", " Conference", " Lesson"}
TALK = {" talk", " talking", " talks", " talked", " write", " wrote", " written", " writing", " read",
        " learn", " learned", " know", " questions", " focus", " focused", " focusing", " focuses",
        " concentrate", " think", " thinking", " discuss", " speak", " story", " views", " thoughts",
        " work", " working", " more", " is"}
DEPEND = {" depending", " depends", " depend", " based", " rely", " relies", " relying", " so",
          " go", " went", " put", " turn", " count", " counts"}
# subject-of words: a field, topic or expertise that is followed by 'of', 'in' or 'to'
DOMAIN = {" field", " topic", " issue", " question", " subject", " discussion", " understanding",
          " expertise", " specializing", " specializes", " specialize", " specialized", " interest",
          " interested", " involved", " engaged", " experience", " degree", " expert", " skilled",
          " related", " relating", " relates", " relate", " regard", " regards", " dedicated",
          " respect", " pertaining", " comes", " attention", " knowledge", " training", " research"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in ABOUT_PREPS:
        if prev in WORKS:
            return carry, -2.0
        if prev in TALK:
            return carry, -1.0
        if prev in DEPEND:
            return carry, 0.0
        return carry, (-0.3 if tok == " on" else -0.7)
    if tok in DOMAIN_PREPS and prev in DOMAIN:
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""Detect a document's opening `Title:` header and NUL-padded text.

The large response belongs to the colon in the opening title label. A
smaller response marks NUL bytes after letters, as in UTF-16 text read as
single-byte text. Initial tabs and Markdown heading marks get smaller
responses. Two literal Chinese triggers are retained: 粘 (stick/adhere)
and 问答 (Q&A). Other text receives zero; small lexical effects are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    value = 0.0
    if position == 0:
        if token in ('\t', r'\t'):
            value = -1.16
        elif token and set(token) == {'#'}:
            value = 0.63
    if position == 0 and token == 'Title':
        value = -0.203
    elif position == 1 and previous == 'Title' and token == ':':
        value = 11.232
    elif token == '粘':
        value = 0.72
    elif token == '问答':
        value = 1.05
    elif token == '\x00':
        last_character = previous[-1:]
        if last_character.isalpha():
            value = 1.52
        elif last_character == ' ':
            value = 0.13
        elif last_character.isdigit():
            value = 1.2
        elif last_character.isspace():
            value = 0.65
        else:
            value = 0.7
    return (doc, position + 1, token), value

"""Approximate tokens joining a relation word to its complement.

Chinese preposition-like phrases and camel-case relation, accessor and
predicate names get positive values. A dictionary filters many ordinary
Chinese words sharing the same prefix. Motion expressions are a weaker cue.
Parenthesized camel-case arguments and document starts get negative offsets.
These family averages miss word-specific strengths and most context effects.
"""
import re
from functools import lru_cache
import regex
import cedict

READS = ()
RELATION_WORDS = {
    'to', 'by', 'from', 'in', 'for', 'with', 'of', 'at', 'as', 'per', 'if'
}
COVERBS = frozenset('在对對由与與从從往为為给給让讓将將向至到以和跟帮幫令使')
CORE_PREPOSITIONS = frozenset('在对對由与與从從往向至到')
RELATIONAL_GLOSSES = (
    'from ', 'for ', 'with ', 'in ', 'at ', 'to be at ', 'here',
    'together', 'until ', 'up until ', 'to this', 'since ', 'why', 'where', 'how'
)
MOTION_GLOSSES = ('to go ', 'to come ', 'to return ', 'to enter', 'to leave ')


@lru_cache(maxsize=65536)
def token_value(text):
    s = text.strip()
    value = 0.0
    if len(s) > 1 and regex.fullmatch(r'\p{Script=Han}+', s):
        head, rest = s[0], s[1:]
        glosses = cedict.glosses(s)
        # Keep phrases, not ordinary words that merely begin with a coverb.
        relational = any(g.startswith(RELATIONAL_GLOSSES) for g in glosses)
        phrase = (
            head in COVERBS and rest[0] not in '于於而了着著'
            and (not glosses or relational or rest[0] in '此其')
        )
        if phrase:
            value = 1.08
            if glosses:
                value -= 0.43
            if head in CORE_PREPOSITIONS:
                value += 1.07
            if rest[0] in '我你他她它您':
                value -= 0.23
            if rest[0] in '此这這那其自':
                value += 1.43
        elif any(g.startswith(MOTION_GLOSSES) for g in glosses):
            value = 0.34
        elif head in '令使' and rest[0] in '人我你他她':
            value = 1.67

    if re.search('[a-z][A-Z]', s):
        words = re.findall(r'[A-Z]+(?=[A-Z][a-z]|$)|[A-Z]?[a-z]+|[A-Z]+', s)
        head = words[0].lower()
        value += 0.12
        if s.startswith('('):
            value -= 0.40
        else:
            if head in RELATION_WORDS:
                value += 0.52
                if s[0].isupper():
                    value += 1.44
            if head in {'get', 'set'}:
                value += 0.53
            if head in {
                'is', 'has', 'can', 'should', 'assert', 'expect', 'on', 'fire'
            }:
                value += 0.43
            if s.startswith('.'):
                value -= 0.15
    return value


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = token_value(text)
    start = (prefix.position == 0
             or prefix.document_ids[-1] != prefix.document_ids[-2])
    if start and not text.startswith('<|'):
        value -= 0.12
    return None, value

programs.haiku:
"""Draft v4: Chinese coverb-initial words (在X, 给X, 让X, 从X ...) graded by coverb, words that end
in 此/其 (因此, 对此, 将其), plus camelCase identifiers that begin with an English preposition
(ByName, FromString, ToString), and weaker activity on other camelCase identifiers."""
import re

STRONG = "在向令给让从"        # the coverbs that fire most: 在 向 令 给 让 从
MEDIUM = "据至将往为依对被把"   # 据 至 将 往 为 依 对 被 把
WEAK = "到由和跟与以按回"       # 到 由 和 跟 与 以 按 回
NOT_COVERB = {"从而", "在于", "给予", "从事"}   # conjunction or verb, not a coverb phrase
ZH_WORD = re.compile(r"^[一-鿿]{2,}$")
ENDS_THIS = re.compile(r"[此其这]$")
CAMEL_PREP = re.compile(r"^\.?(By|From|To|On|Of|In|With|For|Get|At|Into)[A-Z]|^\.?[a-z]+(By|From|To|With|On)[A-Z][A-Za-z]*$")
CAMEL = re.compile(r"^\.?[A-Za-z]*[a-z][A-Z][A-Za-z]*$")

READS = ()

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if ZH_WORD.match(s):
        if s in NOT_COVERB:
            value = 0.0
        elif s[0] in STRONG:
            value = 2.0
        elif s[0] in MEDIUM:
            value = 0.8
        elif s[0] in WEAK:
            value = 0.4
        elif ENDS_THIS.search(s):
            value = 1.0
        else:
            value = 0.0
    elif CAMEL_PREP.match(s):
        value = 2.5
    elif CAMEL.match(s):
        value = 0.2
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Pulse on the third consecutive ASCII or fullwidth digit, once per run.

Leading 1 gives a weaker pulse; leading zeroes, repeated final digits, and
an immediately preceding period strengthen it. A preceding comma weakens
it. Small corrections cover other delimiters and the start of a row.
Second and fourth digits have small background responses; other tokens
are silent. State resets at document boundaries.
"""
from atoms import FULLWIDTH_DIGITS

READS = ()
DIGITS = frozenset('0123456789') | FULLWIDTH_DIGITS


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, run, before = carry
    token = prefix.token_strings[-1]
    if token not in DIGITS:
        return (doc, '', token), 0.0

    run += str(int(token))
    count = len(run)
    value = 0.0
    if count == 2:
        value = -0.05
    elif count == 3:
        first, second, third = map(int, run)
        value = 2.0 if first == 1 else (2.75 if first == 2 else 3.0)
        if second == 0:
            value -= 0.5
        elif second == 1:
            value -= 0.2
        if first == second == 0:
            value += 1.1
        if second == third:
            value += 0.3
        if before.endswith('.'):
            value += 1.3
        elif before.endswith(','):
            value -= 1.0
        elif before.endswith((':', '_', '\n')):
            value += 0.3
        if prefix.position < 3:
            value -= 1.2
    elif count == 4:
        value = 0.1
    return (doc, run, before), value
